/* ---------- Garage ---------- */

.garage-screen { z-index: 12; }
.garage-card {
  width: min(940px, 100%);
  max-height: min(92vh, 780px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.garage-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  flex: 0 0 auto;
}
.garage-head .kicker { margin-bottom: 10px; }
.garage-title {
  margin: 0 0 8px;
  font-family: var(--font-display);
  font-style: italic;
  font-weight: 900;
  font-size: clamp(30px, 4.6vw, 46px);
  letter-spacing: -0.025em;
  line-height: 1;
  color: #fff;
}
.garage-sub {
  margin: 0;
  max-width: 480px;
  font-size: 11.5px;
  line-height: 1.6;
  color: rgba(180, 202, 202, 0.72);
}
.garage-close { flex: 0 0 auto; margin-top: 2px; }
.garage-body {
  display: grid;
  grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
  gap: 16px;
  margin: 18px 0 16px;
  min-height: 0;
  flex: 1 1 auto;
}
.garage-view {
  position: relative;
  min-height: 290px;
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 40%, rgba(58, 226, 255, 0.16), rgba(6, 14, 16, 0) 64%),
    linear-gradient(180deg, #0d1c1f 0%, #070d0f 82%);
  box-shadow: inset 0 0 60px rgba(0, 0, 0, 0.45);
}
#garageCanvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}
.garage-view-badge {
  position: absolute;
  left: 14px;
  bottom: 12px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px 12px 7px;
  border-radius: 9px;
  background: linear-gradient(90deg, rgba(4, 10, 12, 0.78), rgba(4, 10, 12, 0.32) 78%, rgba(4, 10, 12, 0));
  pointer-events: none;
}
.garage-view-badge b {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 26px;
  font-weight: 900;
  letter-spacing: 0.04em;
  color: #fff;
  text-shadow: 0 4px 18px rgba(0, 0, 0, 0.7);
}
.garage-view-badge span {
  font-family: var(--font-display);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent);
}
.garage-view-hint {
  position: absolute;
  right: 13px;
  top: 11px;
  padding: 3px 7px;
  border: 1px solid rgba(58, 226, 255, 0.25);
  border-radius: 999px;
  font-family: var(--font-display);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(58, 226, 255, 0.78);
  background: rgba(5, 14, 16, 0.6);
  pointer-events: none;
}
.garage-list {
  min-height: 0;
  overflow-y: auto;
  padding-right: 3px;
  scrollbar-width: thin;
  scrollbar-color: rgba(58, 226, 255, 0.35) transparent;
}
.garage-list::-webkit-scrollbar { width: 5px; }
.garage-list::-webkit-scrollbar-thumb { background: rgba(58, 226, 255, 0.3); border-radius: 4px; }
.garage-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
  margin: 0;
}
.car-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 12px 8px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.028);
  color: #e9f5f4;
  text-align: center;
  cursor: pointer;
  transition: border-color 0.16s, background 0.16s, transform 0.16s;
}
.car-card:hover:not(.locked) {
  border-color: rgba(58, 226, 255, 0.5);
  background: rgba(58, 226, 255, 0.06);
  transform: translateY(-2px);
}
.car-card.selected {
  border-color: var(--accent);
  background: linear-gradient(180deg, rgba(58, 226, 255, 0.14), rgba(58, 226, 255, 0.04));
  box-shadow: inset 0 0 0 1px rgba(58, 226, 255, 0.35);
}
.car-card.locked {
  opacity: 0.55;
  filter: grayscale(0.65);
  cursor: not-allowed;
  border-style: dashed;
}
.car-card-art {
  display: block;
  width: 42px;
  height: 64px;
  margin-bottom: 3px;
}
.car-card-art svg { display: block; width: 100%; height: 100%; }
.car-card-name {
  font-family: var(--font-display);
  font-size: 12.5px;
  font-weight: 800;
  letter-spacing: 0.12em;
}
.car-card-tag {
  font-family: var(--font-display);
  font-size: 7.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}
.car-stats {
  width: 100%;
  display: grid;
  gap: 3px;
  margin-top: 6px;
}
.car-stat {
  display: flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-display);
  font-size: 6.5px;
  letter-spacing: 0.08em;
  color: rgba(166, 194, 194, 0.72);
}
.car-stat i {
  flex: 1;
  height: 3px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.1);
  overflow: hidden;
}
.car-stat i b {
  display: block;
  height: 100%;
  border-radius: 2px;
  background: var(--car);
}
.car-state {
  margin-top: 6px;
  font-family: var(--font-display);
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
}
.car-card.locked .car-state { color: var(--gold); }
.car-req {
  font-size: 8px;
  line-height: 1.35;
  letter-spacing: 0.04em;
  color: rgba(190, 206, 206, 0.7);
}
.garage-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-top: 1px solid var(--line);
  padding-top: 16px;
}

/* ---------- Responsive ---------- */

@media (max-width: 900px) {
  .logo { font-size: clamp(52px, 14vw, 96px); }
  .title-screen { padding: 8vh 7vw; background: linear-gradient(90deg, rgba(4, 11, 9, 0.94) 0%, rgba(4, 11, 9, 0.7) 55%, rgba(4, 11, 9, 0.35) 100%); }
  .title-foot { display: none; }
}

@media (pointer: coarse), (max-width: 820px) {
  .touch { display: flex; }
  .mobile-note { display: block; }
