      linear-gradient(180deg, rgba(4, 11, 9, 0.55) 0%, rgba(4, 11, 9, 0.82) 46%, rgba(4, 11, 9, 0.96) 100%);
    text-align: center;
  }
  .title-inner { max-width: 460px; }
  .kicker { justify-content: center; font-size: 9.5px; letter-spacing: 0.24em; }
  .logo { font-size: clamp(52px, 16vw, 82px); transform-origin: center bottom; }
