    gap: 10px;
    margin: 12px 0 12px;
  }
  .garage-view { min-height: 0; }
  .garage-view-badge b { font-size: 22px; }
  .garage-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 7px; margin: 0; }
  .car-card-art { width: 34px; height: 52px; }
  .garage-foot { flex-wrap: wrap; }
