  .garage-body { grid-template-rows: minmax(136px, 26vh) minmax(0, 1fr); gap: 9px; margin: 10px 0; }
  .garage-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 7px; margin: 0; }
  .car-card { padding: 9px 5px 8px; }
  .car-card-art { width: 30px; height: 46px; margin-bottom: 1px; }
  .car-card-name { font-size: 11px; }
  .car-card-tag { font-size: 6.5px; }
  .car-stats { gap: 2px; margin-top: 4px; }
  .car-state { margin-top: 4px; font-size: 6.5px; }
  .car-req { font-size: 7px; }
  .garage-title { font-size: 25px; }
  .garage-sub { font-size: 10.5px; }
  .garage-view-badge { left: 10px; bottom: 9px; }
  .garage-view-badge b { font-size: 19px; }
  .garage-view-badge span { font-size: 7px; }
  .garage-foot { flex-direction: column; align-items: stretch; gap: 10px; padding-top: 12px; }
