function buildCarModel(spec) {
  const group = new THREE.Group();
  const body = new THREE.Group();
  group.add(body);

  const paint = new THREE.MeshStandardMaterial({
    color: spec.color,
    metalness: 0.38,
    roughness: 0.36,
