Bright pass shader:
```
uniform sampler2D tDiffuse;
uniform float threshold;
uniform float knee;
varying vec2 vUv;
void main() {
  vec3 c = texture2D(tDiffuse, vUv).rgb;
  float l = dot(c, vec3(0.2126,0.7152,0.0722));
  float soft = clamp((l - threshold + knee) / (2.0*knee), 0.0, 1.0);
  soft = soft*soft*knee; // not right
  float contribution = max(l - threshold, 0.0);
  contribution = max(contribution, soft);
  c *= contribution / max(l, 1e-4);
  gl_FragColor = vec4(c, 1.0);
}
```
Use simple smooth threshold. For bloom strength high, threshold ~0.7.

Blur shader separable 9-tap:
```
uniform sampler2D tDiffuse;
uniform vec2 direction; // texel * radius
varying vec2 vUv;
const float w[5] = float[](0.227027, 0.1945946, 0.1216216, 0.054054, 0.016216);
void main() {
 vec3 sum = texture2D(tDiffuse,vUv).rgb * w[0];
 for i 1..4 sum += (texture2D(tDiffuse, vUv + direction*float(i)) + texture2D(tDiffuse, vUv - direction*float(i))).rgb * w[i];
 gl_FragColor = vec4(sum,1.0);
}
```
