- brightPass sceneRT -> brightA
- blurH brightA -> blurB
- blurV blurB -> blurA
- optional second iteration blurH blurA -> blurB, blurV blurB -> blurA
Then composite sceneRT + blurA.

Composite shader:
```
uniform sampler2D tScene;
uniform sampler2D tBloom;
uniform vec2 texel;
uniform float exposure;
uniform float bloomStrength;
uniform float blurAmount;
varying vec2 vUv;
vec3 aces...
vec3 srgb...
void main() {
  vec2 o = texel * blurAmount;
  vec3 c = texture2D(tScene, vUv).rgb * 0.36;
  c += texture2D(tScene, vUv+vec2(o.x,0)).rgb * 0.16; ... 4 taps
  // 5-tap cross total 1.0
  c += texture2D(tBloom, vUv).rgb * bloomStrength;
  c = ACESFilmic(c);
  gl_FragColor = vec4(linearToSRGB(c), 1.0);
}
