function makeSnowTexture() {
  const rnd = mulberry32(4417);
  return makeTexture(256, 256, (g, w, h) => {
    g.fillStyle = '#dfeaf5';
    g.fillRect(0, 0, w, h);

    // Soft blue drifts.
    for (let i = 0; i < 14; i++) {
      const x = rnd() * w;
      const y = rnd() * h;
      const r = 24 + rnd() * 70;
      const grad = g.createRadialGradient(x, y, 0, x, y, r);
      grad.addColorStop(0, rnd() < 0.5 ? 'rgba(106, 148, 184, 0.2)' : 'rgba(255, 255, 255, 0.24)');
      grad.addColorStop(1, 'rgba(255, 255, 255, 0)');
      g.fillStyle = grad;
      g.beginPath();
      g.arc(x, y, r, 0, Math.PI * 2);
      g.fill();
    }

    // Wind-groomed ridges.
    g.strokeStyle = 'rgba(126, 162, 192, 0.18)';
    g.lineWidth = 1;
    for (let i = -2; i < 12; i++) {
      g.beginPath();
      g.moveTo(-20, i * 26 + rnd() * 8);
      g.bezierCurveTo(w * 0.3, i * 26 - 9, w * 0.66, i * 26 + 13, w + 20, i * 26 - 3);
      g.stroke();
    }

    // Ice crystals.
    for (let i = 0; i < 1200; i++) {
      const x = rnd() * w;
      const y = rnd() * h;
      g.fillStyle = rnd() < 0.5 ? 'rgba(255, 255, 255, 0.72)' : 'rgba(126, 169, 209, 0.34)';
      const s = 0.5 + rnd() * 1.5;
      g.fillRect(x, y, s, s);
    }
  }, { repeat: [31, 25] });
}

function makeSandTexture() {
  const rnd = mulberry32(7741);
  return makeTexture(256, 256, (g, w, h) => {
    g.fillStyle = '#c98a57';
    g.fillRect(0, 0, w, h);

    // Layered sandstone bands.
    for (let i = 0; i < 10; i++) {
      const y = rnd() * h;
      g.fillStyle = rnd() < 0.5 ? 'rgba(112, 58, 31, 0.11)' : 'rgba(248, 198, 143, 0.14)';
      g.beginPath();
      g.moveTo(0, y);
      for (let x = 0; x <= w; x += 16) {
        g.lineTo(x, y + Math.sin(x * 0.05 + i) * 4 + (rnd() - 0.5) * 3);
      }
      g.lineTo(w, y + 18);
      g.lineTo(0, y + 18);
      g.closePath();
      g.fill();
    }

    // Pebbles and grit.
    for (let i = 0; i < 1900; i++) {
      const x = rnd() * w;
      const y = rnd() * h;
      const v = rnd();
      g.fillStyle = v < 0.45
        ? 'rgba(104, 54, 29, 0.4)'
        : v < 0.86
          ? 'rgba(238, 183, 126, 0.34)'
          : 'rgba(255, 226, 183, 0.28)';
      const s = 0.6 + rnd() * 2;
      g.fillRect(x, y, s, s);
    }
  }, { repeat: [34, 27] });
}

function makeCityGroundTexture() {
  const rnd = mulberry32(6613);
  return makeTexture(256, 256, (g, w, h) => {
    g.fillStyle = '#222a33';
    g.fillRect(0, 0, w, h);

    // Concrete panels.
    g.strokeStyle = 'rgba(9, 13, 18, 0.5)';
    g.lineWidth = 2;
    for (let i = 0; i <= 4; i++) {
      const p = (i * w) / 4;
      g.beginPath();
      g.moveTo(p, 0);
      g.lineTo(p, h);
      g.stroke();
      g.beginPath();
      g.moveTo(0, p);
      g.lineTo(w, p);
      g.stroke();
    }

    // Wet stains and neon reflections.
    for (let i = 0; i < 16; i++) {
      const x = rnd() * w;
      const y = rnd() * h;
      const r = 12 + rnd() * 42;
      const neon = rnd() < 0.5 ? [57, 244, 255] : [255, 79, 216];
      const grad = g.createRadialGradient(x, y, 0, x, y, r);
      grad.addColorStop(0, `rgba(${neon[0]}, ${neon[1]}, ${neon[2]}, 0.14)`);
      grad.addColorStop(1, 'rgba(0, 0, 0, 0)');
      g.fillStyle = grad;
      g.beginPath();
      g.arc(x, y, r, 0, Math.PI * 2);
      g.fill();
    }

    for (let i = 0; i < 2400; i++) {
      const x = rnd() * w;
      const y = rnd() * h;
      const v = rnd();
      g.fillStyle = v < 0.55 ? 'rgba(8, 12, 18, 0.28)' : 'rgba(135, 153, 173, 0.14)';
      const s = 0.5 + rnd() * 1.6;
      g.fillRect(x, y, s, s);
    }
  }, { repeat: [36, 29] });
}

function makeWindowTexture() {
  const rnd = mulberry32(9981);
  return makeTexture(128, 256, (g, w, h) => {
    g.fillStyle = '#070b14';
    g.fillRect(0, 0, w, h);

    const cols = 6;
    const rows = 13;
    const cw = w / cols;
    const ch = h / rows;
    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols; col++) {
        const lit = rnd();
        if (lit < 0.52) {
          const palette = ['#7fe8ff', '#ff6ad5', '#ffd58a', '#9ea8ff'];
          g.fillStyle = palette[Math.floor(rnd() * palette.length)];
          g.globalAlpha = 0.35 + rnd() * 0.6;
          g.fillRect(col * cw + 3, row * ch + 3, cw - 6, ch - 7);
        } else if (lit < 0.68) {
          g.fillStyle = 'rgba(122, 148, 190, 0.16)';
          g.fillRect(col * cw + 3, row * ch + 3, cw - 6, ch - 7);
        }
      }
    }
    g.globalAlpha = 1;

    // Vertical structure.
    g.fillStyle = 'rgba(3, 6, 11, 0.72)';
    for (let col = 0; col <= cols; col++) {
      g.fillRect(col * cw - 1, 0, 3, h);
    }
  }, { repeat: [1, 1] });
}

