  const loc = getLocation(selectedLocation);
  titleKicker.textContent = `3D arcade racing · ${loc.tag}`;
  titleTagline.textContent = loc.blurb;
  titleFoot.textContent = `${loc.name} · 3 LAPS · 4 DRIVERS`;
  renderTrackList();
}

function selectLocation(id) {
