import { createRequire } from 'node:module';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');

const config = {
  launchOptions: {
    channel: 'chromium',
    headless: false,
    args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=vulkan', '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface'],
  },
};

const browser = await chromium.launch({ ...config.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(30000);
const errors = [];
page.on('console', (msg) => { if (msg.type() === 'error') errors.push('console: ' + msg.text()); });
page.on('pageerror', (err) => errors.push('pageerror: ' + err.message));
page.on('response', (res) => { if (res.status() >= 400) errors.push(`HTTP ${res.status()} ${res.url()}`); });

await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForFunction(() => !!window.__apex, null, { timeout: 30000 });
await page.waitForTimeout(2500);

const info = await page.evaluate(() => ({
  tracks: document.querySelectorAll('[data-track]').length,
  cars: window.__apex.garageSave ? document.querySelectorAll('[data-car]').length : -1,
  unlocked: window.__apex.garageSave.unlocked,
  selected: window.__apex.garageSave.track,
  mode: window.__apex.state.mode,
}));
console.log('INFO', JSON.stringify(info));
await page.screenshot({ path: '/tmp/opencode/apex-title-ridge.png' });

// Save a title screenshot for every circuit.
for (const id of ['neon', 'alpine', 'canyon', 'ridge']) {
  await page.evaluate((track) => window.__apex.selectLocation(track), id);
  await page.waitForTimeout(900);
  await page.screenshot({ path: `/tmp/opencode/apex-title-${id}.png` });
}

// Start a race on Neon Bay and let it settle.
await page.evaluate(() => window.__apex.selectLocation('neon'));
await page.click('#startBtn');
await page.waitForTimeout(5200);
const raceInfo = await page.evaluate(() => ({
  mode: window.__apex.state.mode,
  raceTime: window.__apex.state.raceTime,
  playerSpeed: window.__apex.playerCar.speed,
  location: window.__apex.world3d.location.id,
  bloom: window.__apex.world3d.postfx.bloomStrength,
  targets: [window.__apex.world3d.postfx.sceneTarget.width, window.__apex.world3d.postfx.sceneTarget.height],
}));
console.log('RACE', JSON.stringify(raceInfo));
await page.screenshot({ path: '/tmp/opencode/apex-race-neon.png' });

// Garage with all cards.
await page.evaluate(() => {
  const a = window.__apex;
  a.state.mode = 'title';
  a.garageSave.unlocked = a.locations.length ? ['apex','jade','blaze','nova','onyx','talon','ember','frost','viper','spectre'] : a.garageSave.unlocked;
});
await page.evaluate(() => {
  // renderGarage is not exported; reload after setting storage instead.
});
await page.evaluate(() => {
  const save = JSON.parse(localStorage.getItem('apex-drift-garage-v1') || '{}');
  save.unlocked = ['apex','jade','blaze','nova','onyx','talon','ember','frost','viper','spectre'];
  save.trackWins = { ridge: 3, neon: 2, alpine: 1, canyon: 1 };
  save.track = 'neon';
  localStorage.setItem('apex-drift-garage-v1', JSON.stringify(save));
});
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => !!window.__apex, null, { timeout: 30000 });
await page.waitForTimeout(1800);
await page.click('#garageBtn');
await page.waitForTimeout(1200);
const garageInfo = await page.evaluate(() => ({
  cards: document.querySelectorAll('[data-car]').length,
  locked: document.querySelectorAll('[data-car].locked').length,
  progress: document.getElementById('garageProgress').textContent,
}));
console.log('GARAGE', JSON.stringify(garageInfo));
await page.screenshot({ path: '/tmp/opencode/apex-garage-all.png' });

console.log('ERRORS', JSON.stringify(errors));
await browser.close();

