import { createRequire } from 'node:module';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');

const args = [
  '--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu',
  '--use-angle=vulkan', '--enable-features=Vulkan', '--use-vulkan=swiftshader',
  '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface',
  '--disable-background-timer-throttling', '--disable-backgrounding-occluded-windows',
  '--disable-renderer-backgrounding', '--disable-gpu-vsync',
];
const browser = await chromium.launch({ channel: 'chromium', headless: false, args, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.setDefaultTimeout(45000);
const errors = [];
page.on('console', (msg) => { if (msg.type() === 'error') errors.push('console: ' + msg.text()); });
page.on('pageerror', (err) => errors.push('pageerror: ' + err.message));

await page.bringToFront();
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForFunction(() => !!window.__apex, null, { timeout: 30000 });
await page.waitForTimeout(1000);

const fps = await page.evaluate(() => new Promise((resolve) => {
  let frames = 0;
  const start = performance.now();
  function tick(now) {
    frames++;
    if (now - start < 1500) requestAnimationFrame(tick);
    else resolve({ frames, ms: now - start });
  }
  requestAnimationFrame(tick);
}));
console.log('FPS', JSON.stringify(fps));

await page.evaluate(() => window.__apex.selectLocation('neon'));
await page.click('#startBtn');
try {
  await page.waitForFunction(() => window.__apex.state.mode === 'racing', null, { timeout: 30000 });
} catch (e) {
  console.log('never racing', await page.evaluate(() => ({ mode: window.__apex.state.mode, countdown: window.__apex.state.countdown })));
}
await page.waitForTimeout(2000);
const info = await page.evaluate(() => ({
  mode: window.__apex.state.mode,
  raceTime: window.__apex.state.raceTime,
  laps: window.__apex.playerCar.laps,
  speed: window.__apex.playerCar.speed,
  kmh: window.__apex.playerCar.kmh,
  pos: window.__apex.playerCar.pos,
  modeText: document.getElementById('lapTime').textContent,
}));
console.log('RACE2', JSON.stringify(info));
await page.screenshot({ path: '/tmp/opencode/apex-race-running.png' });

for (const id of ['alpine', 'canyon', 'ridge', 'neon']) {
  await page.evaluate((track) => window.__apex.selectLocation(track), id);
  await page.waitForTimeout(900);
  await page.screenshot({ path: `/tmp/opencode/apex-race-${id}.png` });
}

// Mobile title + garage layout.
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
mobile.setDefaultTimeout(45000);
const mErrors = [];
mobile.on('pageerror', (err) => mErrors.push(err.message));
mobile.on('console', (msg) => { if (msg.type() === 'error') mErrors.push(msg.text()); });
await mobile.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await mobile.waitForFunction(() => !!window.__apex, null, { timeout: 30000 });
await mobile.waitForTimeout(1800);
await mobile.screenshot({ path: '/tmp/opencode/apex-mobile-title.png' });
await mobile.click('#garageBtn');
await mobile.waitForTimeout(900);
await mobile.screenshot({ path: '/tmp/opencode/apex-mobile-garage.png' });
const mobileInfo = await mobile.evaluate(() => ({
  viewport: [innerWidth, innerHeight],
  tracks: document.querySelectorAll('[data-track]').length,
  cards: document.querySelectorAll('[data-car]').length,
  scrollHeight: document.querySelector('.garage-list')?.scrollHeight,
  clientHeight: document.querySelector('.garage-list')?.clientHeight,
}));
console.log('MOBILE', JSON.stringify(mobileInfo));

console.log('ERRORS', JSON.stringify([...errors, ...mErrors]));
await browser.close();

