export class GameAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.engineGain = null;
    this.tyreGain = null;
    this.osc1 = null;
    this.osc2 = null;
    this.filter = null;
    this.muted = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = new AC();
    this.ctx = ctx;

    const master = ctx.createGain();
    master.gain.value = this.muted ? 0 : 0.6;
    master.connect(ctx.destination);
    this.master = master;

    // Engine: two detuned oscillators through a low-pass filter.
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 420;
    filter.Q.value = 1.1;

    const engineGain = ctx.createGain();
    engineGain.gain.value = 0.0001;

    const osc1 = ctx.createOscillator();
    osc1.type = 'sawtooth';
    osc1.frequency.value = 60;
    const osc2 = ctx.createOscillator();
    osc2.type = 'square';
    osc2.frequency.value = 30;
    const osc2Gain = ctx.createGain();
    osc2Gain.gain.value = 0.55;

    osc1.connect(filter);
    osc2.connect(osc2Gain);
    osc2Gain.connect(filter);
    filter.connect(engineGain);
    engineGain.connect(master);
    osc1.start();
    osc2.start();

    this.filter = filter;
    this.engineGain = engineGain;
    this.osc1 = osc1;
    this.osc2 = osc2;

    // Tyre screech: band-passed noise.
    const seconds = 2;
    const buffer = ctx.createBuffer(1, ctx.sampleRate * seconds, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;

    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    noise.loop = true;

    const band = ctx.createBiquadFilter();
    band.type = 'bandpass';
    band.frequency.value = 1450;
    band.Q.value = 0.85;

    const tyreGain = ctx.createGain();
    tyreGain.gain.value = 0.0001;

    noise.connect(band);
    band.connect(tyreGain);

