page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.removeItem('apex-drift-garage-v1'));
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => !!window.__apex);
const results = await page.evaluate(() => {
  const a = window.__apex;
  const out = [];
  const snap = (label) => out.push({
    label,
    unlocked: [...a.garageSave.unlocked],
    wins: { ...a.garageSave.trackWins },
    races: a.garageSave.races,
  });
