import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({
  channel: 'chromium', headless: false,
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=vulkan', '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface', '--disable-background-timer-throttling', '--disable-backgrounding-occluded-windows', '--disable-renderer-backgrounding'],
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(45000);
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => !!window.__apex);
await page.waitForTimeout(1400);
await page.screenshot({ path: '/tmp/opencode/final-title-ridge.png' });

// Click the Alpine chip like a player and confirm the selection sticks.
await page.click('[data-track="alpine"]');
await page.waitForTimeout(1000);
const afterClick = await page.evaluate(() => ({
  selected: window.__apex.garageSave.track,
  location: window.__apex.world3d.location.id,
  kicker: document.getElementById('titleKicker').textContent,
  foot: document.getElementById('titleFoot').textContent,
  pressed: document.querySelector('[data-track="alpine"]').getAttribute('aria-pressed'),
  saved: JSON.parse(localStorage.getItem('apex-drift-garage-v1')).track,
}));
console.log('AFTER_CLICK', JSON.stringify(afterClick));
await page.screenshot({ path: '/tmp/opencode/final-title-alpine.png' });

// Reload to confirm persistence and start the race to see the banner.
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => !!window.__apex);
await page.waitForTimeout(900);
const restored = await page.evaluate(() => ({
  track: window.__apex.garageSave.track,
  location: window.__apex.world3d.location.id,
}));
console.log('RESTORED', JSON.stringify(restored));
await page.keyboard.press('Enter');
await page.waitForTimeout(600);
await page.screenshot({ path: '/tmp/opencode/final-countdown.png' });
const raceStart = await page.evaluate(() => ({
  mode: window.__apex.state.mode,
  location: window.__apex.world3d.location.id,
  banner: document.getElementById('banner').textContent,
  bannerShown: document.getElementById('banner').classList.contains('show'),
}));
console.log('RACE_START', JSON.stringify(raceStart));
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

