    a.startRace();
    // Skip the countdown.
    a.state.mode = 'racing';
    a.state.countdown = 0;
    const ramp = a.ramps.list[0];
    const back = 250;
    const car = a.playerCar;
    car.pos.x = ramp.x - ramp.tx * (ramp.halfL + back);
    car.pos.y = ramp.z - ramp.ty * (ramp.halfL + back);
    car.angle = Math.atan2(ramp.ty, ramp.tx);
    car.speed = 0;
    car.vx = 0;
    car.vy = 0;
    car.y = 0;
    car.airborne = false;
    a.camera.x = car.pos.x;
    a.camera.y = car.pos.y;
  }, track);
  await page.waitForTimeout(1400);
  await page.screenshot({ path: `/tmp/opencode/ramp-${track}.png` });
}
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

