282: function meetsUnlock(spec) {
283:   if (!spec.unlock) return true;
284:   if (spec.unlock.type === 'races') return garageSave.races >= spec.unlock.count;
285:   if (spec.unlock.type === 'wins') return garageSave.wins >= spec.unlock.count;
286:   if (spec.unlock.type === 'trackWins') {
287:     return (garageSave.trackWins[spec.unlock.track] || 0) >= spec.unlock.count;
288:   }
289:   if (spec.unlock.type === 'tour') {
290:     return spec.unlock.tracks.every(
291:       (track) => (garageSave.trackWins[track] || 0) >= 1
292:     );
293:   }
294:   return false;
295: }
