305: function loadGarage() {
306:   try {
307:     const raw = localStorage.getItem(GARAGE_KEY);
308:     if (raw) {
309:       const data = JSON.parse(raw);
310:       if (data && typeof data === 'object') {
311:         if (typeof data.selected === 'string') garageSave.selected = data.selected;
312:         garageSave.races = Math.max(0, Number(data.races) || 0);
313:         garageSave.wins = Math.max(0, Number(data.wins) || 0);
314:         if (data.trackWins && typeof data.trackWins === 'object') {
315:           for (const loc of LOCATIONS) {
316:             garageSave.trackWins[loc.id] = Math.max(0, Number(data.trackWins[loc.id]) || 0);
317:           }
318:         }
319:         if (typeof data.track === 'string' && LOCATIONS.some((loc) => loc.id === data.track)) {
320:           selectedLocation = data.track;
321:         }
322:         if (Array.isArray(data.unlocked)) {
323:           garageSave.unlocked = data.unlocked.filter((id) => typeof id === 'string');
324:         }
325:       }
326:     }
327:   } catch {
328:     /* Corrupt storage simply starts a fresh garage. */
329:   }
330:   if (!garageSave.unlocked.includes('apex')) garageSave.unlocked.push('apex');
331:   for (const loc of LOCATIONS) {
332:     garageSave.trackWins[loc.id] = Math.max(0, Number(garageSave.trackWins[loc.id]) || 0);
333:   }
334:   garageSave.track = selectedLocation;
335:   for (const spec of PLAYER_CARS) {
336:     if (spec.unlock && meetsUnlock(spec) && !garageSave.unlocked.includes(spec.id)) {
337:       garageSave.unlocked.push(spec.id);
338:     }
339:   }
340:   const chosen = PLAYER_CARS.find((car) => car.id === garageSave.selected);
341:   if (!chosen || !isUnlocked(chosen)) garageSave.selected = 'apex';
342:   saveGarage();
343: }
