832: /* ------------------------------------------------------------------ */
833: /* Race logic                                                          */
834: /* ------------------------------------------------------------------ */
835: 
836: function finishCar(car) {
837:   if (car.finished) return;
838:   car.finished = true;
839:   car.finishTime = state.raceTime;
840:   if (car.isPlayer) {
841:     state.mode = 'finished';
842:     state.resultsTimer = 1.25;
843:     showBanner('FINISH', 2.2);
844:     audio.finish(true);
845:     state.shake = Math.max(state.shake, 0.35);
846:   }
847: }
848: 
849: function updateProgress() {
850:   const N = track.N;
851:   for (const car of cars) {
852:     let delta = car.prevIndex - car.progIndex;
853:     delta = ((delta + N / 2 + N * 2) % N) - N / 2;
854:     car.prog += delta;
855:     car.progIndex = car.prevIndex;
856: 
857:     if (car.finished) continue;
858:     const laps = Math.max(0, Math.floor(car.prog / N));
859:     while (car.laps < laps) {
860:       car.laps++;
861:       const lapTime = state.raceTime - car.lapStart;
862:       if (lapTime > 2) {
863:         car.lapTimes.push(lapTime);
864:         if (car.bestLap === null || lapTime < car.bestLap) car.bestLap = lapTime;
865:       }
866:       car.lapStart = state.raceTime;
867:       if (car.isPlayer && car.laps < LAPS) {
868:         if (car.laps === LAPS - 1) showBanner('FINAL LAP', 2.4);
869:         else showBanner(`LAP ${car.laps + 1} / ${LAPS}`, 1.5);
870:         audio.beep(720, 0.1, 'triangle', 0.05);
871:       }
872:       if (car.laps >= LAPS) {
873:         finishCar(car);
874:         break;
875:       }
876:     }
877:   }
878: }
879: 
880: function standings() {
881:   return [...cars].sort((a, b) => {
882:     if (a.finished && b.finished) {
883:       if (a.finishTime !== b.finishTime) return a.finishTime - b.finishTime;
884:       return b.prog - a.prog;
885:     }
886:     if (a.finished !== b.finished) return a.finished ? -1 : 1;
887:     return b.prog - a.prog;
888:   });
889: }
