894: 
895: function spawnParticle(kind, x, y, vx, vy, size, maxLife, extra = {}) {
896:   if (particles.length > 280) particles.shift();
897:   particles.push({
898:     kind,
899:     x,
900:     y,
901:     vx,
902:     vy,
903:     size,
904:     life: maxLife,
905:     maxLife,
906:     ...extra,
907:   });
908: }
