910: function laySkid(car) {
911:   world3d.laySkid(car);
912: }
913: 
914: function updateEffects(dt) {
915:   for (const car of cars) {
916:     car.wallSoundCd = Math.max(0, car.wallSoundCd - dt);
917: 
918:     // Barrier scrape: throw sparks and shake the camera on a hard hit.
919:     if (car.wallHit > 45) {
920:       const impact = car.wallHit;
921:       car.wallHit = 0;
922:       const count = Math.round(clamp(impact / 55, 2, 9));
923:       for (let k = 0; k < count; k++) {
924:         spawnParticle(
925:           'spark',
926:           car.pos.x + (Math.random() - 0.5) * 18,
927:           car.pos.y + (Math.random() - 0.5) * 18,
928:           (Math.random() - 0.5) * 300,
929:           (Math.random() - 0.5) * 300,
930:           1,
931:           0.22 + Math.random() * 0.3
932:         );
933:       }
934:       if (car.isPlayer) state.shake = Math.max(state.shake, clamp(impact / 320, 0.18, 0.6));
935:       if (car.wallSoundCd <= 0 && impact > 110) {
936:         audio.beep(110, 0.06, 'sawtooth', 0.03);
937:         car.wallSoundCd = 0.2;
938:       }
939:     }
940: 
941:     // Touchdown: a burst of sparks and dust, scaled by fall speed.
942:     if (car.landImpact > 45) {
943:       const impact = car.landImpact;
944:       car.landImpact = 0;
945:       const count = Math.round(clamp(impact / 38, 4, 14));
946:       for (let k = 0; k < count; k++) {
947:         const ang = (k / count) * TAU + Math.random() * 0.5;
948:         const push = 70 + Math.random() * 150;
949:         spawnParticle(
950:           'spark',
951:           car.pos.x + Math.cos(ang) * 12,
952:           car.pos.y + Math.sin(ang) * 12,
953:           Math.cos(ang) * push,
954:           Math.sin(ang) * push,
955:           1,
956:           0.18 + Math.random() * 0.24,
957:           { height: car.y }
958:         );
959:         if (k % 2 === 0) {
960:           spawnParticle(
961:             'dust',
962:             car.pos.x + Math.cos(ang) * 16,
963:             car.pos.y + Math.sin(ang) * 16,
964:             Math.cos(ang) * push * 0.55,
965:             Math.sin(ang) * push * 0.55,
966:             6 + Math.random() * 6,
967:             0.55 + Math.random() * 0.35,
968:             { tint: 'dirt', height: car.y }
969:           );
970:         }
971:       }
972:       if (car.isPlayer) {
973:         state.shake = Math.max(state.shake, clamp(impact / 520, 0.14, 0.55));
974:         if (car.wallSoundCd <= 0) {
975:           audio.beep(72, 0.12, 'triangle', 0.05);
976:           car.wallSoundCd = 0.22;
977:         }
978:       }
979:     }
980: 
981:     if (car.airborne || car.ramp) continue;
982:     if (car.speed < 40) continue;
983:     const cos = Math.cos(car.angle);
984:     const sin = Math.sin(car.angle);
985:     const rearX = car.pos.x - cos * car.length * 0.28;
986:     const rearY = car.pos.y - sin * car.length * 0.28;
987: 
988:     const smoking = car.speed > 110 && (car.input.handbrake || car.slip > 85);
989:     if (smoking) {
990:       laySkid(car);
991:       car.smokeTimer = (car.smokeTimer || 0) - dt;
992:       if (car.smokeTimer <= 0) {
993:         car.smokeTimer = 0.028;
994:         const side = Math.random() < 0.5 ? -1 : 1;
995:         const nx = -sin;
996:         const ny = cos;
997:         spawnParticle(
998:           'smoke',
999:           rearX + nx * 10 * side + (Math.random() - 0.5) * 8,
1000:           rearY + ny * 10 * side + (Math.random() - 0.5) * 8,
1001:           -cos * 26 + (Math.random() - 0.5) * 46,
1002:           -sin * 26 + (Math.random() - 0.5) * 46,
1003:           7 + Math.random() * 7,
1004:           0.72 + Math.random() * 0.45
1005:         );
1006:       }
1007:     }
1008: 
1009:     if (car.surface === 'grass' && car.speed > 70) {
1010:       car.dustTimer = (car.dustTimer || 0) - dt;
1011:       if (car.dustTimer <= 0) {
1012:         car.dustTimer = 0.055;
1013:         spawnParticle(
1014:           'dust',
1015:           car.pos.x - cos * 18 + (Math.random() - 0.5) * 16,
1016:           car.pos.y - sin * 18 + (Math.random() - 0.5) * 16,
1017:           -cos * 24 + (Math.random() - 0.5) * 40,
1018:           -sin * 24 + (Math.random() - 0.5) * 40,
1019:           6 + Math.random() * 6,
1020:           0.65 + Math.random() * 0.35,
1021:           { tint: Math.random() < 0.5 ? 'green' : 'dirt' }
1022:         );
1023:       }
1024:     }
1025:   }
1026: 
1027:   for (let i = particles.length - 1; i >= 0; i--) {
1028:     const p = particles[i];
1029:     p.life -= dt;
1030:     if (p.life <= 0) {
1031:       particles.splice(i, 1);
1032:       continue;
1033:     }
1034:     p.x += p.vx * dt;
1035:     p.y += p.vy * dt;
1036:     const drag = Math.exp(-1.8 * dt);
1037:     p.vx *= drag;
1038:     p.vy *= drag;
1039:   }
1040: 
1041:   state.shake = Math.max(0, state.shake - dt * 2.0);
1042:   if (state.bannerTimer > 0) {
1043:     state.bannerTimer -= dt;
1044:     if (state.bannerTimer <= 0) bannerEl.classList.remove('show');
1045:   }
1046: }
