1048: /* ------------------------------------------------------------------ */
1049: /* Car collisions                                                      */
1050: /* ------------------------------------------------------------------ */
1051: 
1052: function collideCars() {
1053:   for (let i = 0; i < cars.length; i++) {
1054:     for (let j = i + 1; j < cars.length; j++) {
1055:       const a = cars[i];
1056:       const b = cars[j];
1057:       let dx = b.pos.x - a.pos.x;
1058:       let dy = b.pos.y - a.pos.y;
1059:       let dist = Math.hypot(dx, dy);
1060:       const minDist = (a.radius + b.radius) * 1.05;
1061:       if (dist >= minDist) continue;
1062:       if (dist < 0.0001) {
1063:         dx = 1;
1064:         dy = 0;
1065:         dist = 1;
1066:       }
1067:       const nx = dx / dist;
1068:       const ny = dy / dist;
1069:       const overlap = minDist - dist;
1070:       a.pos.x -= nx * overlap * 0.5;
1071:       a.pos.y -= ny * overlap * 0.5;
1072:       b.pos.x += nx * overlap * 0.5;
1073:       b.pos.y += ny * overlap * 0.5;
1074: 
1075:       const rel = (b.vel.x - a.vel.x) * nx + (b.vel.y - a.vel.y) * ny;
1076:       if (rel < 0) {
1077:         const impulse = -rel * 0.55;
1078:         a.vel.x -= nx * impulse;
1079:         a.vel.y -= ny * impulse;
1080:         b.vel.x += nx * impulse;
1081:         b.vel.y += ny * impulse;
1082:         if (-rel > 70) {
1083:           const mx = (a.pos.x + b.pos.x) / 2;
1084:           const my = (a.pos.y + b.pos.y) / 2;
1085:           for (let k = 0; k < 5; k++) {
1086:             spawnParticle(
1087:               'spark',
1088:               mx,
1089:               my,
1090:               (Math.random() - 0.5) * 260,
1091:               (Math.random() - 0.5) * 260,
1092:               1,
1093:               0.25 + Math.random() * 0.25
1094:             );
1095:           }
1096:           if (a.isPlayer || b.isPlayer) state.shake = Math.max(state.shake, 0.55);
1097:         }
1098:       }
1099:     }
1100:   }
1101: }
