1103: /* ------------------------------------------------------------------ */
1104: /* Camera                                                              */
1105: /* ------------------------------------------------------------------ */
1106: 
1107: function updateCamera(dt) {
1108:   if (state.mode === 'title') {
1109:     state.attract += dt * 190;
1110:     const dist = mod(state.attract, track.length);
1111:     const idx = Math.floor(dist / track.ds) % track.N;
1112:     const p = track.points[idx];
1113:     const t = track.tangents[idx];
1114:     const targetX = p.x + t.x * 165;
1115:     const targetY = p.y + t.y * 165;
1116:     camera.x = damp(camera.x, targetX, 2.0, dt);
1117:     camera.y = damp(camera.y, targetY, 2.0, dt);
1118:     camera.zoom = damp(camera.zoom, baseZoom() * (1.0 + Math.sin(state.attract * 0.0011) * 0.035), 1.2, dt);
1119:     return;
1120:   }
1121: 
1122:   const look = state.mode === 'countdown' ? 0.02 : 0.14;
1123:   const targetX = playerCar.pos.x + playerCar.vel.x * look;
1124:   const targetY = playerCar.pos.y + playerCar.vel.y * look;
1125:   camera.x = damp(camera.x, targetX, 6.0, dt);
1126:   camera.y = damp(camera.y, targetY, 6.0, dt);
1127: 
1128:   const speedRatio = clamp(playerCar.speed / playerCar.maxSpeed, 0, 1);
1129:   let zoomTarget = baseZoom() * (1 - 0.1 * speedRatio);
1130:   if (state.mode === 'countdown') zoomTarget *= 1.04;
1131:   camera.zoom = damp(camera.zoom, zoomTarget, 2.6, dt);
1132: }
1133: 
1134: /* ------------------------------------------------------------------ */
1135: /* Simulation step                                                     */
1136: /* ------------------------------------------------------------------ */
1137: 
1138: function step(dt) {
1139:   if (state.mode === 'title') {
1140:     updateCamera(dt);
1141:     return;
1142:   }
1143: 
1144:   if (state.mode === 'paused' || state.mode === 'results') return;
1145: 
1146:   if (state.mode === 'countdown') {
1147:     state.countdown -= dt;
1148:     if (state.countdown <= 0) {
1149:       state.countdown = 0;
1150:       state.mode = 'racing';
1151:       state.started = true;
1152:       state.raceTime = 0;
1153:       cars.forEach((car) => { car.lapStart = 0; });
1154:       showCountdown('GO!');
1155:       audio.countdown(0);
1156:     } else {
1157:       const label = Math.ceil(state.countdown);
1158:       if (label !== state.lastCount) {
1159:         state.lastCount = label;
1160:         showCountdown(String(label));
1161:         audio.countdown(label);
1162:       }
1163:     }
1164:     updateCamera(dt);
1165:     updateEffects(dt);
1166:     state.hudAccum += dt;
1167:     return;
1168:   }
