    g.fillStyle = '#fff6fb';
    g.fillRect(0, 0, w, h);
    g.fillStyle = '#ff4f9f';
    for (let i = -h; i < w + h; i += 26) {
      g.beginPath();
      g.moveTo(i, 0);
      g.lineTo(i + 13, 0);
      g.lineTo(i + 13 + h, h);
      g.lineTo(i + h, h);
      g.closePath();
      g.fill();
    }
  }, { repeat: [10, 2] });
  const archMaterial = new THREE.MeshStandardMaterial({
    map: stripeTexture,
    roughness: 0.48,
    metalness: 0.08,
    emissive: 0x511028,
