    x: WORLD.w / 2 + (cell.c - averageC) * CUSTOM_CELL,
    y: WORLD.h / 2 + (cell.r - averageR) * CUSTOM_CELL,
  });
  const points = route.map(toWorld);
  const rampAnchors = route.filter((cell) => cell.ramp).map(toWorld);
  return {
    layout: {
      cx: WORLD.w / 2,
      cy: WORLD.h / 2,
