window.addEventListener('resize', resize);
loadGarage();
if (selectedLocation !== 'ridge') {
  swapTrackForLocation(getLocation(selectedLocation));
} else {
  setupMinimap();
}
world3d.setLocation(getLocation(selectedLocation));
unlockNewCars();
applyPlayerSetup();
renderGarage();
applyLocationUI();
resetRace();
state.attract = track.length * 0.12;

