/* ---------- Track builder ---------- */

.builder-screen { z-index: 14; }
.builder-card {
  width: min(780px, 100%);
  max-height: min(94vh, 900px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.builder-toolbar {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 16px 0 12px;
  flex: 0 0 auto;
}
.builder-spacer { flex: 1; }
.build-tool,
.builder-small {
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
  color: rgba(218, 238, 236, 0.82);
  font-family: var(--font-display);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  padding: 9px 14px;
  cursor: pointer;
  transition: background 0.16s, border-color 0.16s, color 0.16s;
}
.build-tool:hover,
.builder-small:hover { background: rgba(58, 226, 255, 0.12); border-color: rgba(58, 226, 255, 0.42); }
.build-tool.active {
  background: linear-gradient(100deg, rgba(58, 226, 255, 0.26), rgba(58, 226, 255, 0.08));
  border-color: rgba(58, 226, 255, 0.62);
  color: #fff;
  box-shadow: inset 0 0 0 1px rgba(58, 226, 255, 0.18);
}
.builder-small { padding: 8px 12px; color: rgba(188, 210, 210, 0.7); }
.builder-stage {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background:
    radial-gradient(circle at 50% 42%, rgba(58, 226, 255, 0.055), transparent 68%),
    rgba(4, 12, 12, 0.54);
  overflow: auto;
}
.builder-grid {
  display: grid;
  grid-template-columns: repeat(11, minmax(0, 1fr));
  gap: 5px;
  width: 100%;
  min-width: 430px;
  max-width: 640px;
  margin: 0 auto;
  touch-action: none;
}
.build-cell {
  aspect-ratio: 1;
  position: relative;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 5px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.012));
  color: #061415;
  cursor: crosshair;
  font-family: var(--font-display);
  font-size: 11px;
  font-weight: 900;
  padding: 0;
  transition: background 0.1s, border-color 0.1s;
}
.build-cell:hover { border-color: rgba(58, 226, 255, 0.4); background: rgba(58, 226, 255, 0.09); }
.build-cell.on {
  background:
    linear-gradient(160deg, rgba(58, 226, 255, 0.7), rgba(24, 143, 166, 0.66));
  border-color: rgba(151, 249, 255, 0.72);
  box-shadow: inset 0 0 10px rgba(4, 30, 34, 0.35);
  color: #032226;
}
.build-cell.on.ramp {
  background: linear-gradient(160deg, #ffe27a, #ff9a3c);
  border-color: rgba(255, 242, 176, 0.9);
  color: #3a1b00;
}
.build-cell.start {
  box-shadow: inset 0 0 0 2px #fff, 0 0 14px rgba(58, 226, 255, 0.5);
}
.build-cell span { pointer-events: none; line-height: 1; }
.builder-legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 18px;
  font-family: var(--font-display);
  font-size: 8px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(166, 192, 192, 0.7);
}
.builder-legend span { display: inline-flex; align-items: center; gap: 6px; }
.builder-legend i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }
.legend-track { background: linear-gradient(160deg, #7ff2ff, #1b9eb4); }
.legend-ramp { background: linear-gradient(160deg, #ffe27a, #ff9a3c); }
.legend-start { background: transparent; box-shadow: inset 0 0 0 2px #fff; }
.builder-status {
  min-height: 18px;
  text-align: center;
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(141, 246, 212, 0.88);
}
.builder-status.error { color: #ff9d8f; }
.builder-actions {
  display: flex;
  gap: 9px;
  justify-content: flex-end;
  border-top: 1px solid var(--line);
  margin-top: 14px;
  padding-top: 14px;
  flex: 0 0 auto;
}
.builder-actions .btn-primary { padding: 13px 32px; }
.builder-actions .btn-secondary { padding: 12px 24px; }

/* ---------- Touch controls ---------- */

