import { clamp, damp } from './utils.js';

const PX_PER_KMH = 0.42;

export class Car {
  constructor({ id, name, color, accent, isPlayer = false, number = 1 }) {
    this.id = id;
    this.name = name;
    this.color = color;
    this.accent = accent;
    this.isPlayer = isPlayer;
    this.number = number;

    this.length = 50;
    this.width = 27;
    this.radius = 16;

    this.maxSpeed = isPlayer ? 600 : 585;
    this.accel = isPlayer ? 720 : 690;
    this.brakePower = 1680;
    this.reverseMax = 205;
    this.reverseAccel = 520;
    this.grip = 7.6;

    this.pos = { x: 0, y: 0 };
    this.vel = { x: 0, y: 0 };
    this.angle = 0;
    this.steer = 0;
    this.steerVisual = 0;

    this.speed = 0;
    this.slip = 0;
    this.drifting = false;
    this.surface = 'asphalt';
    this.surfaceMax = this.maxSpeed;
    this.prevIndex = 0;
