function standings() {
  return [...cars].sort((a, b) => {
    if (a.finished && b.finished) {
      if (a.finishTime !== b.finishTime) return a.finishTime - b.finishTime;
      return b.prog - a.prog;
    }
    if (a.finished !== b.finished) return a.finished ? -1 : 1;
    return b.prog - a.prog;
  });
}

