function resetRace() {
  cars.forEach((car, i) => {
    const [behind, lateral] = grid[i];
    const slot = track.gridSlot(behind, lateral);
    car.reset(slot);
    car.prog = -behind / track.ds;
    car.progIndex = slot.index;
    car.prevIndex = slot.index;
    car.lapStart = 0;
    car.smokeTimer = 0;
    car.dustTimer = 0;
    const ai = aiDrivers.get(car);
    if (ai) ai.reset();
  });
  state.raceTime = 0;
  state.countdown = 0;
  state.lastCount = 0;
  state.resultsTimer = 0;
  state.bannerTimer = 0;
  state.shake = 0;
  state.finishPosition = 0;
  state.goTimer = 0;
  state.started = false;
  state.hudAccum = 0;
  state.hudCanvasAccum = 0;
  particles.length = 0;
  world3d.clearSkids();
