      if (!awayFromTrack(x, z, radius + 46)) continue;
      if (!awayFromProps(x, z, radius * 0.7 + 12)) continue;
      if ((x - standX) ** 2 + (z - standZ) ** 2 < 225 ** 2) continue;

      placed.push({ x, z, r: radius });

