/* ---------- Touch controls ---------- */

.touch {
  display: none;
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 8;
  padding: 0 16px calc(14px + var(--safe-bottom));
  align-items: flex-end;
  justify-content: space-between;
  pointer-events: none;
}
.touch-steer, .touch-pedals { display: flex; align-items: flex-end; gap: 10px; pointer-events: none; }
.touch-btn {
  pointer-events: auto;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(9, 20, 20, 0.68);
  color: rgba(235, 250, 249, 0.9);
  touch-action: none;
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.14em;
  display: grid;
  place-items: center;
  border-radius: 50%;
