function ribbonGeometry(track, offsetA, offsetB, y, vScale = 150) {
  const N = track.N;
  const positions = [];
  const uvs = [];
  const indices = [];
  let distance = 0;

  for (let i = 0; i <= N; i++) {
    const index = i % N;
    const p = track.points[index];
    const n = track.normals[index];
    if (i > 0) {
      const prev = track.points[(i - 1) % N];
      distance += Math.hypot(p.x - prev.x, p.y - prev.y);
    }
    positions.push(p.x + n.x * offsetA, y, p.y + n.y * offsetA);
    positions.push(p.x + n.x * offsetB, y, p.y + n.y * offsetB);
    uvs.push(0, distance / vScale, 1, distance / vScale);
  }

  for (let i = 0; i < N; i++) {
    const a = i * 2;
    const b = a + 1;
    const c = a + 2;
    const d = a + 3;
    indices.push(a, b, c, b, d, c);
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

function kerbGeometry(track, side, step = 4) {
  const W = track.width;
  const lo = Math.min(side * (W / 2 - 0.5), side * (W / 2 + 12.5));
  const hi = Math.max(side * (W / 2 - 0.5), side * (W / 2 + 12.5));
  const y = 0.12;
  const positions = [];
  const colors = [];
  const indices = [];

  const red = new THREE.Color(0xd4463f);
  const white = new THREE.Color(0xf1ecdf);
  let vertex = 0;

  for (let start = 0; start < track.N; start += step) {
    const color = Math.floor(start / step) % 2 === 0 ? red : white;
    const before = vertex;
    for (let k = 0; k <= step; k++) {
      const index = (start + k) % track.N;
      const p = track.points[index];
      const n = track.normals[index];
      positions.push(p.x + n.x * lo, y, p.y + n.y * lo);
      positions.push(p.x + n.x * hi, y, p.y + n.y * hi);
      colors.push(color.r, color.g, color.b, color.r, color.g, color.b);
      vertex += 2;
    }
    for (let k = 0; k < step; k++) {
      const a = before + k * 2;
      const b = a + 1;
      const c = a + 2;
      const d = a + 3;
      indices.push(a, b, c, b, d, c);
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

function wallGeometry(track, offset, height) {
  const N = track.N;
  const positions = [];
  const uvs = [];
  const indices = [];
  let distance = 0;

  for (let i = 0; i <= N; i++) {
    const index = i % N;
    const p = track.points[index];
    const n = track.normals[index];
    if (i > 0) {
      const prev = track.points[(i - 1) % N];
      distance += Math.hypot(p.x - prev.x, p.y - prev.y);
    }
    positions.push(p.x + n.x * offset, 0.15, p.y + n.y * offset);
    positions.push(p.x + n.x * offset, height, p.y + n.y * offset);
    uvs.push(distance / 90, 0, distance / 90, 1);
  }

  for (let i = 0; i < N; i++) {
    const a = i * 2;
    const b = a + 1;
    const c = a + 2;
    const d = a + 3;
    indices.push(a, c, b, b, c, d);
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

function quadGeometry() {
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute(
    'position',
    new THREE.Float32BufferAttribute(
      [-0.5, 0, -0.5, 0.5, 0, -0.5, 0.5, 0, 0.5, -0.5, 0, 0.5],
      3
    )
  );
  geometry.setIndex([0, 2, 1, 0, 3, 2]);
  geometry.computeVertexNormals();
  return geometry;
}

function makeInstanced(geometry, material, items) {
  if (!items.length) return null;
  const mesh = new THREE.InstancedMesh(geometry, material, items.length);
  const dummy = new THREE.Object3D();
  items.forEach((item, index) => {
    dummy.position.set(item.x, item.y || 0, item.z);
    dummy.rotation.set(0, item.rot || 0, 0);
    dummy.scale.set(item.sx || 1, item.sy || 1, item.sz || 1);
    dummy.updateMatrix();
    mesh.setMatrixAt(index, dummy.matrix);
    if (item.color) mesh.setColorAt(index, item.color);
  });
  mesh.instanceMatrix.needsUpdate = true;
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  return mesh;
}

/* ------------------------------------------------------------------ */
/* Post-processing                                                     */
/* ------------------------------------------------------------------ */

const FULLSCREEN_VERT = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = vec4(position.xy, 0.0, 1.0);
  }
`;

const BRIGHT_FRAG = `
  uniform sampler2D tScene;
  uniform float threshold;
  uniform float knee;
  varying vec2 vUv;

  void main() {
    vec3 color = texture2D(tScene, vUv).rgb;
    float brightness = max(color.r, max(color.g, color.b));
    float weight = smoothstep(threshold, threshold + knee, brightness);
    gl_FragColor = vec4(color * weight, 1.0);
  }
`;

const BLUR_FRAG = `
  uniform sampler2D tInput;
  uniform vec2 direction;
  varying vec2 vUv;

  void main() {
    vec3 sum = texture2D(tInput, vUv).rgb * 0.2270270270;
    sum += (texture2D(tInput, vUv + direction).rgb + texture2D(tInput, vUv - direction).rgb) * 0.1945945946;
    sum += (texture2D(tInput, vUv + direction * 2.0).rgb + texture2D(tInput, vUv - direction * 2.0).rgb) * 0.1216216216;
    sum += (texture2D(tInput, vUv + direction * 3.0).rgb + texture2D(tInput, vUv - direction * 3.0).rgb) * 0.0540540541;
    sum += (texture2D(tInput, vUv + direction * 4.0).rgb + texture2D(tInput, vUv - direction * 4.0).rgb) * 0.0162162162;
    gl_FragColor = vec4(sum, 1.0);
  }
`;

const COMPOSITE_FRAG = `
  uniform sampler2D tScene;
  uniform sampler2D tBloom;
  uniform vec2 sceneTexel;
  uniform float exposure;
  uniform float bloomStrength;
  uniform float blurPixels;
  varying vec2 vUv;

  vec3 apexRRTAndODTFit(vec3 v) {
    vec3 a = v * (v + 0.0245786) - 0.000090537;
    vec3 b = v * (0.983729 * v + 0.4329510) + 0.238081;
    return a / b;
  }

  vec3 acesFilm(vec3 color) {
    const mat3 inputMat = mat3(
      vec3(0.59719, 0.07600, 0.02840),
      vec3(0.35458, 0.90834, 0.13383),
      vec3(0.04823, 0.01566, 0.83777)
    );
    const mat3 outputMat = mat3(
      vec3(1.60475, -0.10208, -0.00327),
      vec3(-0.53108, 1.10813, -0.07276),
      vec3(-0.07367, -0.00605, 1.07602)
    );
    color *= exposure / 0.6;
    color = inputMat * color;
    color = apexRRTAndODTFit(color);
    color = outputMat * color;
    return clamp(color, 0.0, 1.0);
  }

  vec3 linearToSRGB(vec3 color) {
    vec3 low = color * 12.92;
    vec3 high = pow(max(color, vec3(0.0)), vec3(0.41666)) * 1.055 - 0.055;
    return mix(high, low, vec3(lessThanEqual(color, vec3(0.0031308))));
  }

  void main() {
    vec2 o = sceneTexel * blurPixels;
    vec3 color = texture2D(tScene, vUv).rgb * 0.36;
    color += texture2D(tScene, vUv + vec2(o.x, 0.0)).rgb * 0.16;
    color += texture2D(tScene, vUv - vec2(o.x, 0.0)).rgb * 0.16;
    color += texture2D(tScene, vUv + vec2(0.0, o.y)).rgb * 0.16;
    color += texture2D(tScene, vUv - vec2(0.0, o.y)).rgb * 0.16;
    color += texture2D(tBloom, vUv).rgb * bloomStrength;
    color = acesFilm(color);
    gl_FragColor = vec4(linearToSRGB(color), 1.0);
  }
`;

import { clamp } from './utils.js';

/* ------------------------------------------------------------------ */
/* Ramp definitions                                                    */
/* ------------------------------------------------------------------ */

// Each ramp is anchored to a track sample and centred on its normal. The
// wedge rises from 0 at the base to `height` at the lip along the racing
// direction, so a car crossing it is launched forward and upward.
export const RAMP_DEFS = [
  { index: 46, offset: 0, width: 142, length: 160, height: 34 },
  { index: 114, offset: 12, width: 138, length: 155, height: 30 },
  { index: 307, offset: -8, width: 144, length: 165, height: 38 },
];

/**
 * Pick ramp anchors on the straightest available parts of any circuit. This
 * keeps launches fair across the different layouts without hand-authoring an
 * index table for every location.
 */
export function autoRampDefs(track, count = 3) {
  const N = track.N;
  const defs = [];
  for (let k = 0; k < count; k++) {
    const fraction = count === 1 ? 0.5 : 0.18 + (k / (count - 1)) * 0.64;
    const base = Math.round(N * fraction);
    let best = base;
    let bestCurve = Infinity;
    for (let d = -44; d <= 44; d++) {
      const idx = (base + d + N) % N;
      // Keep ramps away from the start gantry and from each other.
      if (idx < 24 || idx > N - 24) continue;
      const curve = Math.abs(track.curvature[idx]);
      if (curve < bestCurve) {
        bestCurve = curve;
        best = idx;
      }
    }
    defs.push({
      index: best,
      offset: k % 2 === 0 ? 0 : k % 4 === 1 ? 12 : -12,
      width: Math.min(track.width * 0.72, 158),
      length: Math.min(track.width * 0.78, 162),
      height: 30 + (k % 2) * 6,
    });
  }
  return defs;
}

const GRAVITY = 560;
const STEP_HEIGHT = 6;

/* ------------------------------------------------------------------ */
/* Analytical ramp world                                               */
/* ------------------------------------------------------------------ */

export class Ramps {
  constructor(track, defs = RAMP_DEFS) {
    this.list = defs.map((def) => {
      const index = ((def.index % track.N) + track.N) % track.N;
      const p = track.points[index];
      const t = track.tangents[index];
      const n = track.normals[index];
      return {
        ...def,
        index,
        x: p.x + n.x * def.offset,
        z: p.y + n.y * def.offset,
        tx: t.x,
        ty: t.y,
        yaw: -Math.atan2(t.y, t.x),
        slope: Math.atan2(def.height, def.length),
        slopeTan: def.height / def.length,
        halfL: def.length / 2,
        halfW: def.width / 2,
      };
    });
    this._hit = { ramp: null, lx: 0, lz: 0, progress: 0, surface: 0 };
  }

  reset() {
    this._hit.ramp = null;
  }

  // Footprint support query. These allocations are avoided by reusing
  // _hit; callers copy the values they need immediately.
  query(x, z) {
    const hit = this._hit;
    for (const ramp of this.list) {
      const dx = x - ramp.x;
      const dz = z - ramp.z;
      const lx = dx * ramp.tx + dz * ramp.ty;
      if (lx < -ramp.halfL || lx > ramp.halfL) continue;
      const lz = -dx * ramp.ty + dz * ramp.tx;
      if (Math.abs(lz) > ramp.halfW) continue;
      const progress = clamp((lx + ramp.halfL) / ramp.length, 0, 1);
      hit.ramp = ramp;
      hit.lx = lx;
      hit.lz = lz;
      hit.progress = progress;
      hit.surface = ramp.height * progress;
      return hit;
    }
    return null;
  }

  supportHeight(x, z) {
    const hit = this.query(x, z);
    return hit ? hit.surface : 0;
  }

  /**
   * Treat the sides and the vertical lip face as solid walls whenever the
   * car is below the local slope height. The base stays open so the car
   * can drive on from behind. This is a cheap circle-ish vs. oriented box
   * test, run at the fixed 120 Hz physics rate so tunnelling is impossible.
   */
  resolveSolids(car) {
    const nose = car.length / 2;
    for (const ramp of this.list) {
      const dx = car.pos.x - ramp.x;
      const dz = car.pos.y - ramp.z;
      const lx = dx * ramp.tx + dz * ramp.ty;
      if (lx < -ramp.halfL || lx > ramp.halfL + nose) continue;
      const lz = -dx * ramp.ty + dz * ramp.tx;
      if (Math.abs(lz) > ramp.halfW + car.radius) continue;

      const progress = clamp((lx + ramp.halfL) / ramp.length, 0, 1);
      const surface = ramp.height * progress;
      if (car.y + STEP_HEIGHT >= surface) continue;

      let pushLx = 0;
      let pushLz = 0;

      if (lx > ramp.halfL) {
        // Vertical face at the lip. Use the nose length so the body cannot
        // poke through the face before its centre reaches the wall.
        pushLx = ramp.halfL + nose - lx;
      } else {
        // Left or right flank.
        const sign = lz >= 0 ? 1 : -1;
        pushLz = sign * (ramp.halfW + car.radius) - lz;
        if (Math.abs(pushLz) < 0.001) pushLz = sign * (ramp.halfW + car.radius);
      }

      if (pushLz !== 0) {
        car.pos.x += -ramp.ty * pushLz;
        car.pos.y += ramp.tx * pushLz;
        const vLocalZ = -car.vel.x * ramp.ty + car.vel.y * ramp.tx;
        const outward = pushLz >= 0 ? 1 : -1;
        if (vLocalZ * outward < 0) {
          const bounced = -vLocalZ * 0.22;
          const delta = bounced - vLocalZ;
          car.vel.x += -ramp.ty * delta;
          car.vel.y += ramp.tx * delta;
          car.wallHit = Math.max(car.wallHit, Math.abs(vLocalZ));
          car.bump = Math.max(car.bump, 0.55);
        }
      } else if (pushLx > 0) {
        car.pos.x += ramp.tx * pushLx;
        car.pos.y += ramp.ty * pushLx;
        const vLocalX = car.vel.x * ramp.tx + car.vel.y * ramp.ty;
        if (vLocalX < 0) {
          const bounced = -vLocalX * 0.22;
          const delta = bounced - vLocalX;
          car.vel.x += ramp.tx * delta;
          car.vel.y += ramp.ty * delta;
          car.wallHit = Math.max(car.wallHit, Math.abs(vLocalX));
          car.bump = Math.max(car.bump, 0.55);
        }
      }
    }
  }

  /**
   * Vertical state for one car. Mounts the ramp surface, launches off the
   * lip using the climb rate, and integrates a cheap ballistic arc in the
   * air. No rigid-body solver, no raycasts.
   */
  updateCar(car, dt) {
    const hit = this.query(car.pos.x, car.pos.y);

    if (hit && (!car.airborne || car.y <= hit.surface + 2)) {
      // Touching the slope: snap to the exact surface height.
      car.airborne = false;
      car.ramp = hit.ramp;
      car.rampProgress = hit.progress;
      car.y = hit.surface;
      const forward = car.vel.x * hit.ramp.tx + car.vel.y * hit.ramp.ty;
      car.vy = forward * hit.ramp.slopeTan;
      car.climbRate = car.vy;
      this.updatePitch(car, dt);
      return;
    }

    if (hit && car.airborne) {
      // Sailing above a ramp; fall until its deck catches the car.
      this.integrateAir(car, dt, hit.surface);
      if (!car.airborne) {
        car.ramp = hit.ramp;
        car.rampProgress = hit.progress;
      }
      this.updatePitch(car, dt);
      return;
    }

    if (car.ramp) {
      // The centre has left the footprint. If it crossed the lip with
      // height underneath it, carry the climb rate into a jump.
      const ramp = car.ramp;
      const dx = car.pos.x - ramp.x;
      const dz = car.pos.y - ramp.z;
      const lx = dx * ramp.tx + dz * ramp.ty;
      const lz = -dx * ramp.ty + dz * ramp.tx;
      const overLip = lx > ramp.halfL && Math.abs(lz) <= ramp.halfW + 12;
      const height = car.y;
      car.ramp = null;
      car.rampProgress = 0;
      if (height > 1.5) {
        car.airborne = true;
        car.vy = overLip ? Math.max(car.climbRate, 0) : 0;
        car.y = height;
        this.integrateAir(car, dt, 0);
      } else {
        car.y = 0;
        car.vy = 0;
        car.airborne = false;
      }
      this.updatePitch(car, dt);
      return;
    }

    if (car.airborne) {
      this.integrateAir(car, dt, 0);
      this.updatePitch(car, dt);
      return;
    }

    car.y = 0;
    car.vy = 0;
    this.updatePitch(car, dt);
  }

  integrateAir(car, dt, ground) {
    car.vy -= GRAVITY * dt;
    car.y += car.vy * dt;
    if (car.y <= ground) {
      const impact = -car.vy;
      car.y = ground;
      car.vy = 0;
      car.airborne = false;
      if (impact > 45) {
        car.landImpact = Math.max(car.landImpact, impact);
        car.bump = Math.max(car.bump, 0.75);
      }
    }
  }

  updatePitch(car, dt) {
    let target = 0;
    if (car.ramp) {
      const ramp = car.ramp;
      const dot =
        Math.cos(car.angle) * ramp.tx + Math.sin(car.angle) * ramp.ty;
      target = ramp.slope * dot;
    }
    const rate = car.airborne ? 3.0 : car.ramp ? 14 : 9;
    car.pitch += (target - car.pitch) * Math.min(1, rate * dt);
    if (Math.abs(car.pitch) < 0.0002) car.pitch = 0;
  }
}

