  const right = 9;
  const top = 1;
  const bottom = 5;
  for (let c = left; c <= right; c++) {
    cells.push({ c, r: top, ramp: c === 4 });
    cells.push({ c, r: bottom, ramp: c === 6 });
  }
  for (let r = top + 1; r < bottom; r++) {
    cells.push({ c: left, r, ramp: false });
    cells.push({ c: right, r, ramp: false });
  }
  return cells;
}

