content.text:
}

/* ---------- Overlays ---------- */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: flex;
  transition: opacity 0.35s ease, visibility 0.35s;
}
.overlay.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.title-screen {
  align-items: center;
  padding: 6vh 6vw;
  background:
    linear-gradient(90deg, rgba(4, 11, 9, 0.94) 0%, rgba(4, 11, 9, 0.78) 32%, rgba(4, 11, 9, 0.18) 66%, rgba(4, 11, 9, 0) 100%),
    linear-gradient(0deg, rgba(3, 9, 7, 0.85) 0%, transparent 38%);
}

.title-inner {
  max-width: 580px;
  position: relative;
}

.kicker {
  font-size: 10.5px;
  letter-spacing: 0.3em;
  color: rgba(184, 208, 208, 0.5);
  text-transform: uppercase;
  writing-mode: vertical-rl;
  text-orientation: mixed;
}

.center-screen {
  align-items: center;
  justify-content: center;
  padding: 5vh 5vw;
  background:
    radial-gradient(circle at 50% 44%, rgba(10, 30, 30, 0.42) 0%, rgba(3, 9, 8, 0.92) 72%),
    rgba(3, 9, 8, 0.72);
}

.panel-card {
  width: min(560px, 100%);
  max-height: 92vh;
  overflow: auto;
  padding: 34px 38px 32px;
  background: linear-gradient(175deg, rgba(17, 31, 32, 0.96), rgba(8, 15, 16, 0.96));
  border: 1px solid var(--line-strong);
  border-radius: 18px;
  box-shadow: 0 32px 90px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(58, 226, 255, 0.04) inset;
  position: relative;
  overflow: hidden;
  animation: card-in 0.45s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.panel-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, transparent, var(--accent), transparent);
  opacity: 0.8;
}
.panel-card.compact { width: min(430px, 100%); text-align: center; }
.panel-card.compact .kicker { justify-content: center; }
@keyframes card-in {
  from { opacity: 0; transform: translateY(16px) scale(0.98); }
  to { opacity: 1; transform: none; }
}

