const base = 'http://127.0.0.1:9333';
const targetUrl = process.argv[2] || 'http://localhost:8123/';
const expression = process.argv[3] || 'null';
const wait = Number(process.argv[4] || 5000);

const created = await fetch(`${base}/json/new?${encodeURIComponent(targetUrl)}`, { method: 'PUT' }).then(r => r.json());
const ws = new WebSocket(created.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
const events = [];
ws.addEventListener('message', (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  } else if (msg.method) {
    events.push(msg);
  }
});
await new Promise((resolve) => ws.addEventListener('open', resolve, { once: true }));
const send = (method, params = {}) => new Promise((resolve) => {
  const mid = ++id;
  pending.set(mid, resolve);
  ws.send(JSON.stringify({ id: mid, method, params }));
});
await send('Runtime.enable');
await send('Log.enable');
await send('Page.enable');
await new Promise(r => setTimeout(r, wait));
const result = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
const logs = events
  .filter(e => e.method === 'Runtime.consoleAPICalled' || e.method === 'Runtime.exceptionThrown' || e.method === 'Log.entryAdded')
  .map(e => {
    if (e.method === 'Runtime.consoleAPICalled') return `[console.${e.params.type}] ` + e.params.args.map(a => a.value ?? a.description ?? '').join(' ');
    if (e.method === 'Runtime.exceptionThrown') return `[exception] ` + (e.params.exceptionDetails.exception?.description || e.params.exceptionDetails.text);
    return `[log.${e.params.entry.level}] ${e.params.entry.text}`;
  });
console.log(JSON.stringify(result.result?.value ?? result.result, null, 2));
console.log('--- logs ---');
console.log(logs.join('\n'));
ws.close();
await fetch(`${base}/json/close/${created.id}`).catch(() => {});
process.exit(0);

