buildFeatures() {
  this.garageMeshes = [];
  const list = this.features?.list || [];
  if (!list.length) return;

  const track = this.track;
  const W = track.width;
  this.theme.featureSolid = new THREE.MeshStandardMaterial({
    color: 0x313b40,
    roughness: 0.82,
    metalness: 0.12,
  });
  this.theme.featureGlow = new THREE.MeshStandardMaterial({
    color: 0x8ff6ff,
    emissive: 0x39d8ff,
    emissiveIntensity: 0.85,
    roughness: 0.42,
    metalness: 0.2,
  });
  this.theme.featureGlass = new THREE.MeshStandardMaterial({
    color: 0xbfe8e6,
    emissive: 0x2ea7b8,
    emissiveIntensity: 0.26,
    transparent: true,
    opacity: 0.72,
    roughness: 0.25,
    metalness: 0.18,
    side: THREE.DoubleSide,
  });

  const solid = this.theme.featureSolid;
  const glow = this.theme.featureGlow;
  const pillars = [];
  const rails = [];
  const chevrons = [];
  const barriers = [];
  const garageGroups = [];

  for (const f of list) {
    if (f.type === 'dip') {
      // Side retaining walls that follow the dip profile.
      for (let k = 0; k < f.length; k += 2) {
        const idx = mod(f.start + k, track.N);
        const p = track.points[idx];
        const n = track.normals[idx];
        const t = track.tangents[idx];
        const y = this.features.heightAtIndex(idx);
        for (const side of [-1, 1]) {
          pillars.push({
            x: p.x + n.x * side * (W / 2 + 15),
            z: p.y + n.y * side * (W / 2 + 15),
            y: y + 14,
            sx: 5,
            sy: 34,
            sz: Math.max(8, track.ds * 2.4),
            rot: -Math.atan2(t.y, t.x),
          });
        }
      }
      for (const end of [0, f.length - 1]) {
        const idx = mod(f.start + end, track.N);
        const p = track.points[idx];
        const n = track.normals[idx];
        const t = track.tangents[idx];
        chevrons.push({
          x: p.x,
          z: p.y,
          y: 0.4,
          sx: W - 10,
          sy: 0.6,
          sz: 7,
          rot: -Math.atan2(t.y, t.x),
        });
      }
    } else if (f.type === 'bridge') {
      // Support pillars under the elevated deck.
      for (let k = 4; k < f.length - 3; k += 7) {
        const idx = mod(f.start + k, track.N);
        const p = track.points[idx];
        const n = track.normals[idx];
        const t = track.tangents[idx];
        const deck = this.features.heightAtIndex(idx);
        for (const side of [-1, 1]) {
          pillars.push({
            x: p.x + n.x * side * (W / 2 - 16),
            z: p.y + n.y * side * (W / 2 - 16),
            y: deck / 2,
            sx: 11,
            sy: Math.max(4, deck),
            sz: 11,
            rot: -Math.atan2(t.y, t.x),
          });
        }
      }
      for (const end of [2, f.length - 3]) {
        const idx = mod(f.start + end, track.N);
        const p = track.points[idx];
        const n = track.normals[idx];
        const t = track.tangents[idx];
        for (const side of [-1, 1]) {
          rails.push({
            x: p.x + n.x * side * (W / 2 + 5),
            z: p.y + n.y * side * (W / 2 + 5),
            y: this.features.heightAtIndex(idx) + 14,
            sx: 7,
            sy: 8,
            sz: 16,
            rot: -Math.atan2(t.y, t.x),
          });
        }
      }
    } else if (f.type === 'bank') {
      // Bright chevrons on the raised outside edge.
      for (let k = 3; k < f.length - 2; k += 6) {
        const idx = mod(f.start + k, track.N);
        const p = track.points[idx];
        const n = track.normals[idx];
        const t = track.tangents[idx];
        const off = f.side * (W / 2 - 7);
        rails.push({

        rails.push({
          x: p.x + n.x * off,
          z: p.y + n.y * off,
          y: this.features.heightAtIndex(idx) + this.features.bankAtIndex(idx) + 3,
          sx: 16,
          sy: 4,
          sz: 9,
          rot: -Math.atan2(t.y, t.x),
        });
      }
    } else if (f.type === 'chicane') {
      for (const b of this.features.barriers) {
        if (mod(b.index - f.start, track.N) < f.length) barriers.push(b);
      }
    } else if (f.type === 'garage') {
      const group = new THREE.Group();
      group.position.set(f.x, 0, f.z);
      group.rotation.y = f.yaw;
      const depth = Math.max(120, f.lengthPx);
      const roofMat = this.theme.featureGlass.clone();
      roofMat.opacity = 0.62;
      const roof = new THREE.Mesh(
        new THREE.BoxGeometry(depth + 30, 5, W + 46),
        roofMat
      );
      roof.position.y = 92;
      group.add(roof);
      for (const sx of [-1, 1]) {
        for (const sz of [-1, 1]) {
          const column = new THREE.Mesh(
            new THREE.BoxGeometry(9, 92, 9),
            solid
          );
          column.position.set(sz * (depth / 2 - 4), 46, sx * (W / 2 + 12));
          group.add(column);
        }
        const beam = new THREE.Mesh(
          new THREE.BoxGeometry(depth + 18, 6, 5),
          glow
        );
        beam.position.set(0, 85, sx * (W / 2 + 12));
        group.add(beam);
      }
      // Door frames make the covered section readable from a distance.
      for (const sz of [-1, 1]) {
        const frame = new THREE.Mesh(
          new THREE.BoxGeometry(5, 9, W + 30),
          glow
        );
        frame.position.set(sz * (depth / 2), 74, 0);
        group.add(frame);
      }
      group.traverse((object) => {
        if (object.isMesh) object.castShadow = false;
      });
      garageGroups.push({ group, roofMat, feature: f });
      this.scene.add(group);
    }
  }

  if (pillars.length) {
    this.scene.add(makeInstanced(new THREE.BoxGeometry(1, 1, 1), solid, pillars));
  }
  if (rails.length) {
    this.scene.add(makeInstanced(new THREE.BoxGeometry(1, 1, 1), glow, rails));
  }
  if (chevrons.length) {
    this.scene.add(makeInstanced(new THREE.BoxGeometry(1, 1, 1), glow, chevrons));
  }
  if (barriers.length) {
    const stripe = new THREE.MeshStandardMaterial({
      color: 0xffe7ea,
      emissive: 0xff6a8a,
      emissiveIntensity: 0.55,
      roughness: 0.52,
    });
    this.theme.chicane = stripe;
    for (const b of barriers) {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(b.halfLen * 2, 16, b.halfWidth * 2),
        stripe
      );
      mesh.position.set(b.x, 8, b.z);
      mesh.rotation.y = b.yaw;
      this.scene.add(mesh);
    }
  }

  this.garageMeshes = garageGroups;
}

