226: /**
227:  * A valid builder loop is a single connected cycle of four-way neighbours.
228:  * Each tile must touch exactly two other tiles. This rejects blobs, branches,
229:  * diagonal joins and open lines before they become an undrivable circuit.
230:  */
231: function traceBuilderLoop(cells) {
232:   if (!Array.isArray(cells) || cells.length < 8) {
233:     return { ok: false, error: 'Paint at least 8 track tiles to make a loop.' };
234:   }
235:   const map = new Map();
236:   for (const cell of cells) map.set(keyOf(cell), cell);
237: 
238:   const neighbours = (cell) =>
239:     [
240:       map.get(`${cell.c + 1},${cell.r}`),
241:       map.get(`${cell.c - 1},${cell.r}`),
242:       map.get(`${cell.c},${cell.r + 1}`),
243:       map.get(`${cell.c},${cell.r - 1}`),
244:     ].filter(Boolean);
245: 
246:   for (const cell of cells) {
247:     if (neighbours(cell).length !== 2) {
248:       return {
249:         ok: false,
250:         error: 'Every tile needs exactly two neighbours. Erase branches or fill diagonal gaps.',
251:       };
252:     }
253:   }
254: 
255:   const route = [];
256:   let previous = null;
257:   let current = cells[0];
258:   let closed = false;
259:   for (let guard = 0; guard <= cells.length; guard++) {
260:     route.push(current);
261:     const options = neighbours(current).filter((cell) => cell !== previous);
262:     const next = options[0];
263:     if (!next) break;
264:     if (next === route[0]) {
265:       closed = true;
266:       break;
267:     }
268:     if (route.includes(next)) break;
269:     previous = current;
270:     current = next;
271:   }
272: 
273:   if (!closed || route.length !== cells.length) {
274:     return { ok: false, error: 'The tiles must form one closed loop, not separate paths.' };
275:   }
276:   return { ok: true, route };
277: }
