628: const UPGRADE_MAX = 3;
629: const UPGRADE_BASE_COST = 220;
630: const UPGRADE_KEYS = ['speed', 'accel', 'grip'];
631: 
632: function carUpgrades(id) {
633:   if (!garageSave.upgrades[id]) {
634:     garageSave.upgrades[id] = { speed: 0, accel: 0, grip: 0 };
635:   }
636:   return garageSave.upgrades[id];
637: }
638: 
639: function upgradeCost(level) {
640:   return UPGRADE_BASE_COST * (level + 1);
641: }
642: 
643: function buyUpgrade(id, key) {
644:   const spec = PLAYER_CARS.find((car) => car.id === id);
645:   if (!spec || !isUnlocked(spec) || !UPGRADE_KEYS.includes(key)) return;
646:   const upgrades = carUpgrades(id);
647:   const level = upgrades[key] || 0;
648:   if (level >= UPGRADE_MAX) return;
649:   const cost = upgradeCost(level);
650:   if (garageSave.credits < cost) {
651:     audio.beep(150, 0.12, 'sawtooth', 0.04);
652:     return;
653:   }
654:   garageSave.credits -= cost;
655:   upgrades[key] = level + 1;
656:   saveGarage();
657:   applyPlayerSetup();
658:   renderGarage();
659:   audio.beep(880, 0.1, 'square', 0.05);
660: }
