675: function meetsUnlock(spec) {
676:   if (!spec.unlock) return true;
677:   if (spec.unlock.type === 'races') return garageSave.races >= spec.unlock.count;
678:   if (spec.unlock.type === 'wins') return garageSave.wins >= spec.unlock.count;
679:   if (spec.unlock.type === 'trackWins') {
680:     return (garageSave.trackWins[spec.unlock.track] || 0) >= spec.unlock.count;
681:   }
682:   if (spec.unlock.type === 'tour') {
683:     return spec.unlock.tracks.every(
684:       (track) => (garageSave.trackWins[track] || 0) >= 1
685:     );
686:   }
687:   return false;
688: }
