698: function loadGarage() {
699:   try {
700:     const raw = localStorage.getItem(GARAGE_KEY);
701:     if (raw) {
702:       const data = JSON.parse(raw);
703:       if (data && typeof data === 'object') {
704:         if (typeof data.selected === 'string') garageSave.selected = data.selected;
705:         garageSave.races = Math.max(0, Number(data.races) || 0);
706:         garageSave.wins = Math.max(0, Number(data.wins) || 0);
707:         garageSave.credits = Math.max(0, Number(data.credits) || 0);
708:         garageSave.explosive = Boolean(data.explosive);
709:         if (data.upgrades && typeof data.upgrades === 'object') {
710:           for (const spec of PLAYER_CARS) {
711:             const saved = data.upgrades[spec.id];
712:             if (!saved || typeof saved !== 'object') continue;
713:             const levels = { speed: 0, accel: 0, grip: 0 };
714:             for (const key of UPGRADE_KEYS) {
715:               levels[key] = Math.max(0, Math.min(UPGRADE_MAX, Math.round(Number(saved[key]) || 0)));
716:             }
717:             garageSave.upgrades[spec.id] = levels;
718:           }
719:         }
720:         if (data.trackWins && typeof data.trackWins === 'object') {
721:           for (const loc of LOCATIONS) {
722:             garageSave.trackWins[loc.id] = Math.max(0, Number(data.trackWins[loc.id]) || 0);
723:           }
724:         }
725:         if (typeof data.track === 'string' && LOCATIONS.some((loc) => loc.id === data.track)) {
726:           selectedLocation = data.track;
727:         }
728:         if (Array.isArray(data.custom)) {
729:           const clean = sanitizeCells(data.custom);
730:           if (clean && traceBuilderLoop(clean).ok) customCells = clean;
731:         }
732:         if (Array.isArray(data.unlocked)) {
733:           garageSave.unlocked = data.unlocked.filter((id) => typeof id === 'string');
734:         }
735:       }
736:     }
737:   } catch {
738:     /* Corrupt storage simply starts a fresh garage. */
739:   }
740:   if (!garageSave.unlocked.includes('apex')) garageSave.unlocked.push('apex');
741:   for (const loc of LOCATIONS) {
742:     garageSave.trackWins[loc.id] = Math.max(0, Number(garageSave.trackWins[loc.id]) || 0);
743:   }
744:   garageSave.track = selectedLocation;
745:   customTrackData = makeCustomTrackData(customCells);
746:   garageSave.custom = serializeCells(customCells);
747:   for (const spec of PLAYER_CARS) carUpgrades(spec.id);
748:   for (const spec of PLAYER_CARS) {
749:     if (spec.unlock && meetsUnlock(spec) && !garageSave.unlocked.includes(spec.id)) {
750:       garageSave.unlocked.push(spec.id);
751:     }
752:   }
753:   const chosen = PLAYER_CARS.find((car) => car.id === garageSave.selected);
754:   if (!chosen || !isUnlocked(chosen)) garageSave.selected = 'apex';
755:   saveGarage();
756: }
