970: function renderBuilderGrid() {
971:   const trace = traceBuilderLoop(builderCells);
972:   const map = new Map(builderCells.map((cell) => [keyOf(cell), cell]));
973:   const start = trace.ok ? trace.route[0] : null;
974:   const parts = [];
975:   for (let r = 0; r < CUSTOM_ROWS; r++) {
976:     for (let c = 0; c < CUSTOM_COLS; c++) {
977:       const cell = map.get(`${c},${r}`);
978:       const classes = ['build-cell'];
979:       if (cell) classes.push('on');
980:       if (cell && cell.ramp) classes.push('ramp');
981:       if (cell && cell.feature) classes.push('feature', `feat-${cell.feature}`);
982:       if (start && cell === start) classes.push('start');
983:       const info = cell && cell.feature ? FEATURE_INFO[cell.feature] : null;
984:       const label = cell
985:         ? cell.feature
986:           ? info.short.slice(0, 2)
987:           : cell.ramp
988:             ? 'R'
989:             : start && cell === start
990:               ? 'S'
991:               : ''
992:         : '';
993:       const detail = cell
994:         ? cell.feature
995:           ? `, ${info.label}, rotated ${((cell.rotation || 0) * 90)} degrees`
996:           : cell.ramp
997:             ? ', ramp tile'
998:             : ', track tile'
999:         : ', empty';
1000:       parts.push(
1001:         `<button class="${classes.join(' ')}" data-c="${c}" data-r="${r}" type="button" aria-label="Grid ${c + 1}, ${r + 1}${detail}">
1002:           <span>${label}</span>
1003:         </button>`
1004:       );
1005:     }
1006:   }
1007:   builderGrid.innerHTML = parts.join('');
1008:   updateBuilderStatus(trace);
1009: }
