1011: function updateBuilderStatus(trace = traceBuilderLoop(builderCells)) {
1012:   if (trace.ok) {
1013:     const ramps = builderCells.filter((cell) => cell.ramp).length;
1014:     const feats = builderCells.filter((cell) => cell.feature).length;
1015:     builderStatus.textContent = `Loop ready · ${builderCells.length} tiles · ${ramps} ramp${ramps === 1 ? '' : 's'} · ${feats} feature${feats === 1 ? '' : 's'} · rot ${builderRotation * 90}°`;
1016:     builderStatus.classList.remove('error');
1017:     builderRaceBtn.disabled = false;
1018:   } else {
1019:     builderStatus.textContent = trace.error;
1020:     builderStatus.classList.add('error');
1021:     builderRaceBtn.disabled = true;
1022:   }
1023: }
