1025: function applyBuilderTool(c, r) {
1026:   const index = builderCells.findIndex((cell) => cell.c === c && cell.r === r);
1027:   let changed = false;
1028:   if (builderTool === 'erase') {
1029:     if (index >= 0) {
1030:       builderCells.splice(index, 1);
1031:       changed = true;
1032:     }
1033:   } else if (builderTool === 'track') {
1034:     if (index < 0) {
1035:       builderCells.push({ c, r, ramp: false, feature: null, rotation: 0 });
1036:       changed = true;
1037:     } else if (builderCells[index].ramp || builderCells[index].feature) {
1038:       builderCells[index].ramp = false;
1039:       builderCells[index].feature = null;
1040:       builderCells[index].rotation = 0;
1041:       changed = true;
1042:     }
1043:   } else if (builderTool === 'ramp') {
1044:     if (index < 0) {
1045:       builderCells.push({ c, r, ramp: true, feature: null, rotation: 0 });
1046:       changed = true;
1047:     } else if (!builderCells[index].ramp) {
1048:       builderCells[index].ramp = true;
1049:       builderCells[index].feature = null;
1050:       builderCells[index].rotation = 0;
1051:       changed = true;
1052:     }
1053:   } else if (FEATURE_TYPES.includes(builderTool)) {
1054:     if (index < 0) {
1055:       builderCells.push({
1056:         c,
1057:         r,
1058:         ramp: false,
1059:         feature: builderTool,
1060:         rotation: builderRotation,
1061:       });
1062:       changed = true;
1063:     } else {
1064:       builderCells[index].ramp = false;
1065:       builderCells[index].feature = builderTool;
1066:       builderCells[index].rotation = builderRotation;
1067:       changed = true;
1068:     }
1069:   }
1070:   if (changed) renderBuilderGrid();
1071: }
