1073: function buildAndRace() {
1074:   const trace = traceBuilderLoop(builderCells);
1075:   if (!trace.ok) {
1076:     updateBuilderStatus(trace);
1077:     audio.beep(140, 0.16, 'sawtooth', 0.04);
1078:     return;
1079:   }
1080:   customCells = builderCells.map((cell) => ({ ...cell }));
1081:   customTrackData = makeCustomTrackData(customCells);
1082:   garageSave.custom = serializeCells(customCells);
1083:   selectedLocation = 'custom';
1084:   garageSave.track = 'custom';
1085:   saveGarage();
