732: function applyCarStyle(model, spec, force = false) {
733:   const key = `${spec.color}|${spec.accent}|${spec.number}`;
734:   if (!force && model.styleKey === key) return;
735:   model.styleKey = key;
736:   model.paint.color.set(spec.color);
737:   model.accent.color.set(spec.accent);
738:   if (model.ring) model.ring.material.color.set(spec.color);
739:   if (model.roundelMat.map) model.roundelMat.map.dispose();
740:   model.roundelMat.map = makeRoundelTexture(spec.number);
741:   model.roundelMat.needsUpdate = true;
742:   model.spec = { ...spec };
743: }
