746: /* Geometry builders                                                   */
747: /* ------------------------------------------------------------------ */
748: 
749: function profileY(track, features, index, offset, baseY) {
750:   if (!features) return baseY;
751:   const half = Math.max(1, track.width / 2);
752:   const lateral = clamp(offset / half, -1, 1);
753:   return baseY + features.heightAtIndex(index) + features.bankAtIndex(index) * lateral;
754: }
755: 
756: function ribbonGeometry(track, offsetA, offsetB, y, vScale = 150, features = null) {
757:   const N = track.N;
758:   const positions = [];
759:   const uvs = [];
760:   const indices = [];
761:   let distance = 0;
762: 
763:   for (let i = 0; i <= N; i++) {
764:     const index = i % N;
765:     const p = track.points[index];
766:     const n = track.normals[index];
767:     if (i > 0) {
768:       const prev = track.points[(i - 1) % N];
769:       distance += Math.hypot(p.x - prev.x, p.y - prev.y);
770:     }
771:     positions.push(
772:       p.x + n.x * offsetA,
773:       profileY(track, features, index, offsetA, y),
774:       p.y + n.y * offsetA
775:     );
776:     positions.push(
777:       p.x + n.x * offsetB,
778:       profileY(track, features, index, offsetB, y),
779:       p.y + n.y * offsetB
780:     );
781:     uvs.push(0, distance / vScale, 1, distance / vScale);
782:   }
783: 
784:   for (let i = 0; i < N; i++) {
785:     const a = i * 2;
786:     const b = a + 1;
787:     const c = a + 2;
788:     const d = a + 3;
789:     indices.push(a, b, c, b, d, c);
790:   }
791: 
792:   const geometry = new THREE.BufferGeometry();
793:   geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
794:   geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
795:   geometry.setIndex(indices);
796:   geometry.computeVertexNormals();
797:   return geometry;
798: }
799: 
800: function kerbGeometry(track, side, step = 4, features = null) {
801:   const W = track.width;
802:   const lo = Math.min(side * (W / 2 - 0.5), side * (W / 2 + 12.5));
803:   const hi = Math.max(side * (W / 2 - 0.5), side * (W / 2 + 12.5));
804:   const y = 0.12;
805:   const positions = [];
806:   const colors = [];
807:   const indices = [];
808: 
809:   const red = new THREE.Color(0xd4463f);
810:   const white = new THREE.Color(0xf1ecdf);
811:   let vertex = 0;
812: 
813:   for (let start = 0; start < track.N; start += step) {
814:     const color = Math.floor(start / step) % 2 === 0 ? red : white;
815:     const before = vertex;
816:     for (let k = 0; k <= step; k++) {
817:       const index = (start + k) % track.N;
818:       const p = track.points[index];
819:       const n = track.normals[index];
820:       positions.push(
821:         p.x + n.x * lo,
822:         profileY(track, features, index, lo, y),
823:         p.y + n.y * lo
824:       );
825:       positions.push(
826:         p.x + n.x * hi,
827:         profileY(track, features, index, hi, y),
828:         p.y + n.y * hi
829:       );
830:       colors.push(color.r, color.g, color.b, color.r, color.g, color.b);
831:       vertex += 2;
832:     }
833:     for (let k = 0; k < step; k++) {
834:       const a = before + k * 2;
835:       const b = a + 1;
836:       const c = a + 2;
837:       const d = a + 3;
838:       indices.push(a, b, c, b, d, c);
839:     }
840:   }
841: 
842:   const geometry = new THREE.BufferGeometry();
843:   geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
844:   geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
845:   geometry.setIndex(indices);
846:   geometry.computeVertexNormals();
847:   return geometry;
848: }
849: 
850: function wallGeometry(track, offset, height, features = null) {
851:   const N = track.N;
852:   const positions = [];
853:   const uvs = [];
854:   const indices = [];
855:   let distance = 0;
856: 
857:   for (let i = 0; i <= N; i++) {
858:     const index = i % N;
859:     const p = track.points[index];
860:     const n = track.normals[index];
861:     if (i > 0) {
862:       const prev = track.points[(i - 1) % N];
863:       distance += Math.hypot(p.x - prev.x, p.y - prev.y);
864:     }
865:     const base = profileY(track, features, index, offset, 0.15);
866:     positions.push(p.x + n.x * offset, base, p.y + n.y * offset);
867:     positions.push(p.x + n.x * offset, base + height, p.y + n.y * offset);
868:     uvs.push(distance / 90, 0, distance / 90, 1);
869:   }
870: 
871:   for (let i = 0; i < N; i++) {
872:     const a = i * 2;
873:     const b = a + 1;
874:     const c = a + 2;
875:     const d = a + 3;
876:     indices.push(a, c, b, b, c, d);
877:   }
878: 
879:   const geometry = new THREE.BufferGeometry();
880:   geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
881:   geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
882:   geometry.setIndex(indices);
883:   geometry.computeVertexNormals();
884:   return geometry;
885: }
886: 
887: function quadGeometry() {
888:   const geometry = new THREE.BufferGeometry();
889:   geometry.setAttribute(
890:     'position',
891:     new THREE.Float32BufferAttribute(
892:       [-0.5, 0, -0.5, 0.5, 0, -0.5, 0.5, 0, 0.5, -0.5, 0, 0.5],
893:       3
894:     )
895:   );
896:   geometry.setIndex([0, 2, 1, 0, 3, 2]);
897:   geometry.computeVertexNormals();
898:   return geometry;
899: }
900: 
901: function makeInstanced(geometry, material, items) {
902:   if (!items.length) return null;
903:   const mesh = new THREE.InstancedMesh(geometry, material, items.length);
904:   const dummy = new THREE.Object3D();
905:   items.forEach((item, index) => {
906:     dummy.position.set(item.x, item.y || 0, item.z);
907:     dummy.rotation.set(0, item.rot || 0, 0);
908:     dummy.scale.set(item.sx || 1, item.sy || 1, item.sz || 1);
909:     dummy.updateMatrix();
910:     mesh.setMatrixAt(index, dummy.matrix);
911:     if (item.color) mesh.setColorAt(index, item.color);
912:   });
913:   mesh.instanceMatrix.needsUpdate = true;
914:   if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
915:   return mesh;
916: }
