918: /* ------------------------------------------------------------------ */
919: /* Post-processing                                                     */
920: /* ------------------------------------------------------------------ */
921: 
922: const FULLSCREEN_VERT = `
923:   varying vec2 vUv;
924:   void main() {
925:     vUv = uv;
926:     gl_Position = vec4(position.xy, 0.0, 1.0);
927:   }
928: `;
929: 
930: const BRIGHT_FRAG = `
931:   uniform sampler2D tScene;
932:   uniform float threshold;
933:   uniform float knee;
934:   varying vec2 vUv;
935: 
936:   void main() {
937:     vec3 color = texture2D(tScene, vUv).rgb;
938:     float brightness = max(color.r, max(color.g, color.b));
939:     float weight = smoothstep(threshold, threshold + knee, brightness);
940:     gl_FragColor = vec4(color * weight, 1.0);
941:   }
942: `;
943: 
944: const BLUR_FRAG = `
945:   uniform sampler2D tInput;
946:   uniform vec2 direction;
947:   varying vec2 vUv;
948: 
949:   void main() {
950:     vec3 sum = texture2D(tInput, vUv).rgb * 0.2270270270;
951:     sum += (texture2D(tInput, vUv + direction).rgb + texture2D(tInput, vUv - direction).rgb) * 0.1945945946;
952:     sum += (texture2D(tInput, vUv + direction * 2.0).rgb + texture2D(tInput, vUv - direction * 2.0).rgb) * 0.1216216216;
953:     sum += (texture2D(tInput, vUv + direction * 3.0).rgb + texture2D(tInput, vUv - direction * 3.0).rgb) * 0.0540540541;
954:     sum += (texture2D(tInput, vUv + direction * 4.0).rgb + texture2D(tInput, vUv - direction * 4.0).rgb) * 0.0162162162;
955:     gl_FragColor = vec4(sum, 1.0);
956:   }
957: `;
958: 
959: const COMPOSITE_FRAG = `
960:   uniform sampler2D tScene;
961:   uniform sampler2D tBloom;
962:   uniform vec2 sceneTexel;
963:   uniform float exposure;
964:   uniform float bloomStrength;
965:   uniform float blurPixels;
966:   varying vec2 vUv;
967: 
968:   vec3 apexRRTAndODTFit(vec3 v) {
969:     vec3 a = v * (v + 0.0245786) - 0.000090537;
970:     vec3 b = v * (0.983729 * v + 0.4329510) + 0.238081;
971:     return a / b;
972:   }
973: 
974:   vec3 acesFilm(vec3 color) {
975:     const mat3 inputMat = mat3(
976:       vec3(0.59719, 0.07600, 0.02840),
977:       vec3(0.35458, 0.90834, 0.13383),
978:       vec3(0.04823, 0.01566, 0.83777)
979:     );
980:     const mat3 outputMat = mat3(
981:       vec3(1.60475, -0.10208, -0.00327),
982:       vec3(-0.53108, 1.10813, -0.07276),
983:       vec3(-0.07367, -0.00605, 1.07602)
984:     );
985:     color *= exposure / 0.6;
986:     color = inputMat * color;
987:     color = apexRRTAndODTFit(color);
988:     color = outputMat * color;
989:     return clamp(color, 0.0, 1.0);
990:   }
991: 
992:   vec3 linearToSRGB(vec3 color) {
993:     vec3 low = color * 12.92;
994:     vec3 high = pow(max(color, vec3(0.0)), vec3(0.41666)) * 1.055 - 0.055;
995:     return mix(high, low, vec3(lessThanEqual(color, vec3(0.0031308))));
996:   }
997: 
998:   void main() {
999:     vec2 o = sceneTexel * blurPixels;
1000:     vec3 color = texture2D(tScene, vUv).rgb * 0.36;
1001:     color += texture2D(tScene, vUv + vec2(o.x, 0.0)).rgb * 0.16;
1002:     color += texture2D(tScene, vUv - vec2(o.x, 0.0)).rgb * 0.16;
1003:     color += texture2D(tScene, vUv + vec2(0.0, o.y)).rgb * 0.16;
1004:     color += texture2D(tScene, vUv - vec2(0.0, o.y)).rgb * 0.16;
1005:     color += texture2D(tBloom, vUv).rgb * bloomStrength;
1006:     color = acesFilm(color);
1007:     gl_FragColor = vec4(linearToSRGB(color), 1.0);
1008:   }
1009: `;
1010: 
1011: class WorldPostFX {
1012:   constructor(renderer) {
1013:     this.renderer = renderer;
1014:     this.exposure = 1.1;
1015:     this.bloomStrength = 1;
1016:     this.blurPixels = 1.25;
1017: 
1018:     const canFloat =
1019:       renderer.capabilities.isWebGL2 &&
1020:       (renderer.extensions.has('EXT_color_buffer_float') ||
1021:         renderer.extensions.has('EXT_color_buffer_half_float'));
1022:     this.bufferType = canFloat ? THREE.HalfFloatType : THREE.UnsignedByteType;
1023: 
1024:     const targetOptions = {
1025:       type: this.bufferType,
1026:       minFilter: THREE.LinearFilter,
1027:       magFilter: THREE.LinearFilter,
1028:       depthBuffer: true,
1029:       stencilBuffer: false,
1030:     };
1031:     this.sceneTarget = new THREE.WebGLRenderTarget(1, 1, targetOptions);
1032:     this.brightTarget = new THREE.WebGLRenderTarget(1, 1, {
1033:       ...targetOptions,
1034:       depthBuffer: false,
1035:     });
1036:     this.blurTargetA = new THREE.WebGLRenderTarget(1, 1, {
1037:       ...targetOptions,
1038:       depthBuffer: false,
1039:     });
1040:     this.blurTargetB = new THREE.WebGLRenderTarget(1, 1, {
1041:       ...targetOptions,
1042:       depthBuffer: false,
1043:     });
1044: 
1045:     this.fxScene = new THREE.Scene();
1046:     this.fxCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
1047:     this.quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), null);
1048:     this.quad.frustumCulled = false;
1049:     this.fxScene.add(this.quad);
1050: 
1051:     const base = {
1052:       vertexShader: FULLSCREEN_VERT,
1053:       depthTest: false,
1054:       depthWrite: false,
1055:     };
1056: 
1057:     this.brightMaterial = new THREE.ShaderMaterial({
1058:       ...base,
1059:       uniforms: {
1060:         tScene: { value: null },
1061:         threshold: { value: 0.8 },
1062:         knee: { value: 0.22 },
1063:       },
1064:       fragmentShader: BRIGHT_FRAG,
1065:     });
1066: 
1067:     this.blurMaterial = new THREE.ShaderMaterial({
1068:       ...base,
1069:       uniforms: {
1070:         tInput: { value: null },
1071:         direction: { value: new THREE.Vector2(1, 0) },
1072:       },
1073:       fragmentShader: BLUR_FRAG,
1074:     });
1075: 
1076:     this.compositeMaterial = new THREE.ShaderMaterial({
1077:       ...base,
1078:       uniforms: {
1079:         tScene: { value: null },
1080:         tBloom: { value: null },
1081:         sceneTexel: { value: new THREE.Vector2(1, 1) },
1082:         exposure: { value: this.exposure },
1083:         bloomStrength: { value: this.bloomStrength },
1084:         blurPixels: { value: this.blurPixels },
1085:       },
1086:       fragmentShader: COMPOSITE_FRAG,
1087:     });
1088: 
1089:     this.blurRadius = 1.15;
1090:     this.bloomTexel = new THREE.Vector2(1, 1);
1091:     this.enabled = true;
1092: 
1093:     for (const target of [this.sceneTarget, this.brightTarget, this.blurTargetA, this.blurTargetB]) {
1094:       target.texture.generateMipmaps = false;
1095:     }
1096:   }
1097: 
1098:   setSize(width, height, pixelRatio) {
1099:     const w = Math.max(1, Math.floor(width * pixelRatio));
1100:     const h = Math.max(1, Math.floor(height * pixelRatio));
1101:     if (w === this.width && h === this.height) return;
1102:     this.width = w;
1103:     this.height = h;
1104: 
1105:     this.sceneTarget.setSize(w, h);
1106:     const bw = Math.max(1, Math.floor(w / 4));
1107:     const bh = Math.max(1, Math.floor(h / 4));
1108:     this.bloomWidth = bw;
1109:     this.bloomHeight = bh;
1110:     this.brightTarget.setSize(bw, bh);
1111:     this.blurTargetA.setSize(bw, bh);
1112:     this.blurTargetB.setSize(bw, bh);
1113:     this.compositeMaterial.uniforms.sceneTexel.value.set(1 / w, 1 / h);
1114:     this.bloomTexel.set(1 / bw, 1 / bh);
1115:   }
1116: 
1117:   setLook(look) {
1118:     this.exposure = look.exposure ?? 1.1;
1119:     this.bloomStrength = look.bloomStrength ?? 1;
1120:     this.blurPixels = look.blurPixels ?? 1.25;
1121:     this.blurRadius = look.blurRadius ?? 1.15;
1122:     this.brightMaterial.uniforms.threshold.value = look.threshold ?? 0.8;
1123:     this.brightMaterial.uniforms.knee.value = look.knee ?? 0.22;
1124:     this.compositeMaterial.uniforms.exposure.value = this.exposure;
1125:     this.compositeMaterial.uniforms.bloomStrength.value = this.bloomStrength;
1126:     this.compositeMaterial.uniforms.blurPixels.value = this.blurPixels;
1127:   }
1128: 
1129:   render(scene, camera) {
1130:     const renderer = this.renderer;
1131: 
1132:     renderer.setRenderTarget(this.sceneTarget);
1133:     renderer.clear();
1134:     renderer.render(scene, camera);
1135: 
1136:     // Bright pass at quarter resolution.
1137:     this.quad.material = this.brightMaterial;
1138:     this.brightMaterial.uniforms.tScene.value = this.sceneTarget.texture;
1139:     renderer.setRenderTarget(this.brightTarget);
1140:     renderer.render(this.fxScene, this.fxCamera);
1141: 
1142:     // Two separable gaussian passes give a wide, soft bloom at low cost.
1143:     this.quad.material = this.blurMaterial;
1144:     let source = this.brightTarget;
1145:     let destination = this.blurTargetA;
1146:     for (let pass = 0; pass < 2; pass++) {
1147:       this.blurMaterial.uniforms.tInput.value = source.texture;
1148:       this.blurMaterial.uniforms.direction.value.set(
1149:         this.bloomTexel.x * this.blurRadius,
1150:         0
1151:       );
1152:       renderer.setRenderTarget(destination);
1153:       renderer.render(this.fxScene, this.fxCamera);
1154: 
1155:       this.blurMaterial.uniforms.tInput.value = destination.texture;
1156:       this.blurMaterial.uniforms.direction.value.set(
1157:         0,
1158:         this.bloomTexel.y * this.blurRadius
1159:       );
1160:       renderer.setRenderTarget(source);
1161:       renderer.render(this.fxScene, this.fxCamera);
1162:     }
1163: 
1164:     this.quad.material = this.compositeMaterial;
1165:     this.compositeMaterial.uniforms.tScene.value = this.sceneTarget.texture;
1166:     this.compositeMaterial.uniforms.tBloom.value = source.texture;
1167:     renderer.setRenderTarget(null);
1168:     renderer.render(this.fxScene, this.fxCamera);
1169:   }
1170: }
